insert into site_settings ("id", "siteName", "siteNameEn", "tagline", "logoPath", "logoAlt", "faviconPath", "logoIncludesName", "blockAdminIndex", "phone", "whatsapp", "whatsappMessage", "email", "address", "city", "country", "mapEmbedUrl", "mapLinkUrl", "workingHoursJson", "socialsJson", "heroBadge", "heroTitle", "heroDescription", "heroImage", "heroImageAlt", "homeAboutTitle", "homeAboutText", "homeAboutImage", "homeAboutImageAlt", "homeServicesTitle", "homeServicesText", "homeServicesCtaText", "homeProgramsTitle", "homeProgramsText", "homeBlogTitle", "homeBlogText", "homeTestimonialsTitle", "homeFaqTitle", "homeFaqText", "finalCtaBadge", "finalCtaTitle", "finalCtaText", "aboutHeroTitle", "aboutHeroText", "aboutWhoTitle", "aboutWhoText", "aboutVisionTitle", "aboutVisionText", "aboutMissionTitle", "aboutMissionText", "aboutValuesTitle", "aboutValuesText", "aboutVision2030Title", "aboutVision2030Text", "aboutVision2030Image", "aboutWhyTitle", "aboutWhyText", "seoTitle", "seoDescription", "seoKeywords", "ogImage", "analyticsCode", "notifyEmailEnabled", "notificationEmail", "notifyOnNewClient", "notifyOnNewMessage", "notifyOnNewBooking", "primaryColor", "accentColor", "createdAt", "updatedAt") values
    ('singleton', 'سوار وعي', 'Sewr Waie', 'مركز الإحاطة بعلوم التعافي', NULL, NULL, NULL, false, true, '+966 55 200 5282', '+966 55 200 5282', 'السلام عليكم، أرغب في الاستفسار عن خدمات مركز سوار وعي.', 'info@sewrwaie.com', 'طريق الملك عبدالعزيز، حي العليا', 'الرياض', 'المملكة العربية السعودية', NULL, NULL, '[{"day":"الأحد – الخميس","hours":"9:00 صباحًا – 9:00 مساءً"},{"day":"الجمعة","hours":"مغلق"},{"day":"السبت","hours":"مغلق"}]', '{"instagram":"https://instagram.com/","x":"https://x.com/","linkedin":"https://linkedin.com/","youtube":"https://youtube.com/"}', 'مركز متخصص في علوم التعافي', 'وعي يقود للتعافي.. وتعافٍ يصنع حياة أفضل', 'مركز متخصص في علاج الإدمان والإرشاد النفسي والعلمي. نبدأ بتقييم دقيق، ثم نضع خطة علاج متكاملة تمضي معك نحو التغيير النفسي والاجتماعي والديني، باحترام وخصوصية كاملة.', '/placeholders/hero-sunrise.svg', 'شخص جالس على صخرة يواجه شروق الشمس', 'من نحن', 'سوار وعي مركز متخصص في علوم الإدمان والاضطرابات النفسية والسلوكية. نسعى لتقديم رعاية متكاملة تُعنّى بالفرد والأسرة والمجتمع، تقوم على الأسس العلمية الحديثة، وتحفظ كرامة كل من يطلب المساعدة دون أحكام مسبقة.', '/placeholders/about-center.svg', 'منطقة استقبال في مركز سوار وعي', 'خدمات متكاملة لرحلة تعافٍ مستدامة', 'يقدم سوار وعي خدمات متكاملة في مجال علاج الإدمان والاضطرابات النفسية والسلوكية، ونسعى لتوجيه كل شخص لما يناسبه من برامج وخدمات.', 'تفاصيل خدماتنا', 'منهجية التعافي', 'في سوار وعي لا نعمل إلا وفق منهجية واضحة. نضع لكل مستفيد خطة متدرجة تبدأ بفهم الوضع الحالي، ثم تمهّد الطريق نحو التغيير، وتنتهي بالمتابعة طويلة المدى.', 'التغيير ممكن.. ونحن هنا لدعمك', 'اقرأ أحدث ما نشاركه من وعي ومعرفة', 'كلمات من راجعوا تجربتهم معنا', 'أسئلة يطرحها كثيرون', 'إجابات واضحة عن أكثر ما يُسأل عنه عند طلب المساعدة أو البدء في رحلة التعافي.', 'رسالةنا الختامية', 'التغيير ممكن.. ونحن هنا لدعمك', 'لا نعدك بمعجزات، لأن التعافي قرار يتّخذ كل يوم. نعدك بأننا لن نتركك وحدك: سنسمعك، ونفهم وضعك، ونبني معك خطة تناسب حياتك، ونرافقك حتى تستقر.', 'من نحن', 'ند تمتد للمدمنين الراغبين في التعافي ولأسرهم وللمؤسسات التعليمية والتأهيلية؛ تثقيفًا وتعريفًا بأحدث النظم والبرامج التي تساعد في نشر الوعي والثقافة والمعرفة العلمية لبلوغ الأهداف.', 'من نحن', '«سوار وعي» مركز متخصص في الإحاطة بعلوم التعافي، يعمل على تقديم الرعاية النفسية والعلمية المتخصصة في تعديل السلوك، وتنفيذ البرامج العلاجية والإرشادية في إعادة تأهيل المدمنين.

كما يقدّم دعماً للأسر والمؤسسات التعليمية والتأهيلية لنشر المعرفة العلمية. نعمل وفق أسس علمية واضحة ومعايير مهنية، مع احترام كامل لخصوصية من يطلب المساعدة ولعائلته. نحن لا نُدين أحدًا، ولا نُصنّف الناس، بل نعمل على تعديل السلوك وتحسين القدرة على العيش بما يناسب كل فرد.', 'رؤيتنا', 'لسنا الأوائل، ولكننا نطمح بأن نكون الأكفأ والأكبر تأثيرًا لخدمة مستفيدينا ومجتمعنا؛ أن نكون شريكًا موثوقًا في رحلة التعافي، ومرجعًا يثق به الناس في المعلومة في موضوع يحبه الناس أن يسألوا عنه.', 'رسالتنا', 'نحيطك بوعي، ونحتوي الألم معًا.', 'قيمنا', 'هذه هي البوصلة التي نسترشد بها في كل قرار داخل المركز:', 'ارتباطنا برؤية 2030', 'نؤمن بأن العمل التوعوي، وبناء القدرات، وإتاحة برامج إعادة التأهيل، تصنع أثرًا مجتمعيًا حقيقيًا. وحين نشارك في هذه الرؤية، لا نبحث عن أرقام فقط، بل عن أثر يشعر به من يمر بنا ومن حوله.', '/placeholders/vision2030.svg', 'لماذا تختارنا', 'خمسة أسباب تجعل سوار وعي خيارًا مختلفًا في رحلة التعافي:', 'سوار وعي | مركز الإحاطة بعلوم التعافي وعلاج الإدمان', 'مركز سوار وعي للإحاطة بعلوم التعافي: رعاية نفسية وعلمية متخصصة في تعافي الإدمان، وبرامج إعادة تأهيل، وإرشاد أسري، وتوعية مجتمعية.', 'سوار وعي, Sewr Waie, علاج الإدمان, إعادة التأهيل, الصحة النفسية, الإرشاد الأسري, الوقاية, الرياض, السعودية', NULL, NULL, true, 'admin@sewrwaie.sa', true, true, true, '#4B2A7B', '#D9A441', '2026-10-04T11:58:23.213Z'::timestamptz, '2026-10-04T11:58:23.213Z'::timestamptz)
on conflict ("id") do nothing;

