insert into process_steps ("id", "title", "description", "icon", "order", "isActive") values
    ('cmutroqo90007uedcew56c85f', 'التقييم والاستماع', 'نبدأ بفهم وضعك الفعلي تقنيًا ونفسيًا واجتماعيًا قبل أي خطوة.', 'Compass', 0, true),
    ('cmutroqoc0008uedcli0mw9xw', 'التغيير', 'تجربة عملية في تعديل السلوك عبر جلسات فردية وجماعية منظّمة.', 'Sprout', 1, true),
    ('cmutroqog0009uedcbuhdntoy', 'الدافعية', 'نساعدك على رؤية موقعك ضمن مراحل التغيير وتبني خطة واقعية.', 'Target', 2, true),
