insert into why_items ("id", "title", "description", "icon", "order", "isActive") values
    ('cmutroqp7000huedcq9dqnvr8', 'الإنسان أولًا', 'نبدأ من الإنسان لا من التشخيص. كل خطة تُبنى على ما يريده المستفيد وقدراته الحقيقية، لا على قوالب جاهزة.', 'Heart', 0, true),
    ('cmutroqpa000iuedchh7hscbs', 'الاحترافية', 'نلتزم بالمعايير المهنية، ونستند إلى ما هو معتمد علميًا، ونعرف حدود تخصّصنا ونوجّه إلى غيرنا عند الحاجة.', 'Target', 1, true),
    ('cmutroqpd000juedc0x2y3aap', 'الجودة', 'لا نكتفي بتقديم خدمة، بل نراجعها ونقيس أثرها ونحسّنها باستمرار استنادًا إلى تغذية راجعة منظمة.', 'Gem', 2, true),
    ('cmutroqpg000kuedczetvzw98', 'الاستمرارية', 'التعافي يحتاج متابعة. نرافق المستفيد حتى بعد استقرار الوضع، لأن أصعب المرحلة هي التي تأتي بعد التحسّن.', 'CalendarCheck', 3, true),
    ('cmutroqpj000luedcyz5kx03l', 'الوعي', 'نعمل على نشر المعرفة العلمية، لأن الوعي هو خط الدفاع الأول ضد الوصم.', 'Lightbulb', 4, true)
on conflict ("id") do nothing;

