insert into testimonials ("id", "quote", "authorName", "authorRole", "rating", "isAnonymous", "image", "order", "isActive", "createdAt") values
    ('cmutroqq0000quedc66dw4upl', 'دخلت المركز وأنا لا أعرف من أين أبدأ. أول ما فعلوه أن استمعوا لي دون أن يحكموا عليّ. هذه كانت الخطوة التي لم أتوقعها.', NULL, 'مستفيد من برنامج إعادة التأهيل', 5, true, NULL, 0, true, '2026-10-04T11:58:23.305Z'::timestamptz),
    ('cmutroqq4000ruedcdsz6c5p1', 'أهمّ ما تغيّر هو علاقتي بأسرتي. كنا نتجنب الحديث، والآن صار هناك حوار حقيقي بيننا. جزاكم الله خيرًا.', NULL, 'أسرة مستفيد', 5, true, NULL, 1, true, '2026-10-04T11:58:23.309Z'::timestamptz),
    ('cmutroqq8000suedcz4u6nyoe', 'المجموعة الأسبوعية صارت موعدًا أنتظره. في اليوم الذي انكسر فيها كل شيء، لم أكن وحدي، وهذا ما أنقذني.', NULL, 'مستفيد من الجلسات الجماعية', 5, true, NULL, 2, true, '2026-10-04T11:58:23.312Z'::timestamptz),
    ('cmutroqqb000tuedcxov542o3', 'أُدير مؤسسة تعليمية، وطلبنا ورشة لطلابنا. احترموا السرّية تمامًا، والمحتوى كان واقعيًا لا وعظيًا، واخترنا تزويد فرقنا بتدريب عملي ممتاز.', NULL, 'مؤسسة تعليمية', 5, true, NULL, 3, true, '2026-10-04T11:58:23.315Z'::timestamptz)
on conflict ("id") do nothing;

insert into faqs ("id", "question", "answer", "category", "order", "isActive") values
    ('cmutroqqf000uuedc0j79u5kb', 'هل أحتاج إلى إحالة طبية لبدء الخدمة؟', 'لا. يمكنك التواصل معنا مباشرة دون إحالة. يبدأ كل مسار بتقييم مبيّن على حالتك، وإذا احتجت إلى تدخل طبي نوجّهك إلى الطبيب المختص وننسّق معه بإشرافك.', 'عام', 0, true),
    ('cmutroqqi000vuedckbdbcq6g', 'هل خدماتكم سرّية؟', 'نعم، السرّية مبدأ نلتزم به دون استثناء: كل ما يطّلع عليه الفريق يبقى داخل المركز ولا يُشارك مع أي طرف خارجي دون إذنك الصريح، ونحفظ بياناتك مشفّرة في نظام آمن.', 'عام', 1, true),
    ('cmutroqql000wuedcqxlee6go', 'كم تستغرق جلسة الاستشارة الأولى؟', 'تستغرق عادة بين ثلاثين وخمسين دقيقة. هي لقاء تعارف وتقييم في آن واحد، ننتهي منه بخطة أولية واضحة ومعرفة الخطوة التالية.', 'عام', 2, true),
    ('cmutroqqo000xuedcz0uu92ex', 'متى أطلب المساعدة؟', 'كلما كان الطلب أبكر كان التعامل أسهل. لا تنتظر حتى تدهور الوضع. تكرار المحاولات الفاشلة، أو تراجع الأداء في العمل والدراسة، أو تأثر العلاقات الأسرية، كلها علامات تستدعي التواصل.', 'التعافي', 3, true),
    ('cmutroqqr000yuedcnem59891', 'كم يستغرق التعافي؟', 'المدة تختلف من شخص لآخر ولا يمكن تحديدها بمعادار ثابتة. ما نقدر على تحديده هو المسار: مراحل واضحة ومؤشرات تقدّم قابلة للقياس، ومتابعة حتى بعد التحسّن.', 'التعافي', 4, true),
    ('cmutroqqv000zuedcfeklpo53', 'ماذا لو حدثت انتكاسة؟', 'الانتكاسة احتمال قائم في أي مسار تعافٍ وليست نهاية الطريق. نعاملها كإشارة على تعديل الخطة: نراجع ما الذي تغيّر، وما الذي يحتاج تغييرًا، ثم نواصل معك كأن شيئًا لم يحدث.', 'التعافي', 5, true),
    ('cmutroqqy0010uedcsjk9tm20', 'كم تكلفة الخدمات؟', 'تختلف تكلفة الخدمة حسب البرنامج وطبيعة الحالة. نقدّم تقديرًا واضحًا بعد التقييم الأولي، ونعلمك بأي تكاليف قبل البدء دون مفاجآت.', 'الأسعار', 6, true),
    ('cmutroqr10011uedcnv4ptu09', 'هل توجد جلسات مجانية أو مخفّضة؟', 'نعم، نوفّر برامج دعم محدودة بسعر مخفّض، وندعم الحالات التي تحتاجها فعلاً عبر برامج الشراكة. تواصل معنا لبحث الخيار المناسب دون إحراج.', 'الأسعار', 7, true),
    ('cmutroqr40012uedck3seekxn', 'هل أستطيع حضور جلسات Family؟', 'نعم. نوفّر جلسات أسرية خاصة، وغالبًا تكون مفيدة جدًا خاصة في بداية الطريق حين يحتاج مقدّم الرعاية إلى فهم أوضح للظاهرة.', 'الأسرة', 8, true),
    ('cmutroqr70013uedc5boujccr', 'كيف أتعامل مع شخص في حالة إدمان داخل بيتي؟', 'ابدأ بالتثقيف: افهم آلية الظاهرة قبل أن تتصرف. ثم ركّز على بناء علاقة دافئة بلا متابعة يومية، وعلى وضع حدود واضحة، وعلى طلب المساعدة المتخصصة في وقتها بدل تحمّل الموقف وحدك.', 'الأسرة', 9, true),
    ('cmutroqra0014uedcodlhqgg0', 'هل يمكن للمرأة طلب المساعدة لابنها أو زوجها دون حضوره؟', 'نعم، ولا يُشترط حضور المستفيد لطلب الاستشارة الأولية. وبطبيعة الحال لا نشارك أي معلومات عنه دون إذنه الصريح.', 'الأسرة', 10, true),
    ('cmutroqrd0015uedcjhin13vu', 'هل تقدمون برامج للمؤسسات التعليمية؟', 'نعم، ننفّذ برامج وقائية وتوعوية، وبرامج تأهيلية تُدار بسرّية تامة داخل المؤسسة. تواصل معنا عبر نموذج الاستفسار لتحديد البرنامج المناسب.', 'الجامعات والمدارس', 11, true)
on conflict ("id") do nothing;

insert into content_items ("id", "type", "slug", "title", "shortDescription", "fullDescription", "icon", "image", "imageAlt", "audience", "stepsJson", "benefitsJson", "outcomesJson", "notesJson", "durationLabel", "faqsJson", "seoTitle", "seoDescription", "order", "isActive", "isFeatured", "createdAt", "updatedAt") values
    ('cmutroqsl001fuedcvgqewz30', 'PROGRAM', 'barmoj-matrix', 'برنامج ماتريكس', 'نظام منظّم يجمع معطيات الفحص الطبي والنفسي والاجتماعي، ويحوّلها إلى خطة عملية متفق عليها.', '<p>برنامج ماتريكس ليس نموذجًا جاهزًا يُطبَّق آليًا، بل نظام منظّم يجمع المعطيات من أكثر من زاوية ويضعها في صورة واحدة. حين يرى المستفيد حالته في خريطة واحدة، تصبح الخطة قابلة للفهم والمناقشة والتعديل.</p>
<p>المعطيات التي نجمعها تأتي من الفحص الطبي، ومن التقييم النفسي، ومن المعاينة الاجتماعية، ومن معاينة نمط السلوك. ولا نغني طرفًا عن آخر، فكل زاوية تكشف جانبًا لا تراه الزوايا الأخرى.</p>
<h2>ما الذي يشمله التقييم؟</h2>
<p>يُجرى التقييم على جلسات متتابعة لا في لقاء واحد عابر، لأن بعض المعطيات تحتاج وقتًا لتظهر، ولأن الثقة التي تجعل الإجابة صادقة تحتاج هي أيضًا وقتًا.</p>
<ul>
<li><strong>الجانب الطبي:</strong> سجل الفحوصات، والأعراض الجسدية، والأدوية المستخدمة حاليًا إن وُجدت، بالتنسيق مع الطبيب المختص.</li>
<li><strong>الجانب النفسي:</strong> المزاج والمشاعر واضطرابات المصاحبة وعلاقتها بالسلوك.</li>
<li><strong>الجانب الاجتماعي:</strong> الأسرة والسكن والعمل والعلاقات ومستوى الدعم المتاح.</li>
<li><strong>الجانب السلوكي:</strong> نمط الاستخدام، والمواقف المحفّزة، والأوقات التي يتكرر فيها.</li>
<li><strong>الأهداف والأولويات:</strong> ما الذي يريد المستفيد تغييره أولًا، وما واقعه الآن.</li>
</ul>', 'ClipboardList', NULL, NULL, 'كل من يبدأ رحلة التعافي، ومن يحتاج إلى خريطة طريق واضحة قبل الدخول في أي برنامج.', '[{"title":"جمع المعطيات","description":"لقاءات تقييم عبر أكثر من زاوية: طبية، ونفسية، واجتماعية، وسلوكية."},{"title":"ربط المعطيات","description":"نضع النتائج في صورة واحدة، ونحدّد ما هو واضح وما يحتاج إلى تحقق."},{"title":"عرض الخطة","description":"نعرض الخطة على المستفيد بلغة يفهمها، ونسمع ملاحظاته قبل اعتمادها."},{"title":"المراجعة الدورية","description":"تُراجع الخطة على فترات محددة وتُعدَّل بحسب ما يظهر من استجابة."}]', '["خطة مبنية على معطيات موثقة لا على انطباع","فهم أوضح لواقع المستفيد وللمحاور التي تحتاج أولوية","تناسق بين الفريق بدل اجتهاد كل فرد على حدة","مرجع واضح يمكن الرجوع إليه عند كل مراجعة","تعديل مبكر للخطة بدل اكتشاف الخلل متأخرًا"]', '["خطة تعافٍ مكتوبة يفهمها المستفيد","أولويات واضحة للعمل في الأسابيع القادمة","تناسق بين الجوانب الطبية والنفسية والاجتماعية","قرارات لاحقة مبنية على قراءة معطيات الحالة"]', '["مدته تُحدَّد بحسب حالة كل مستفيد، وهو ليس اختبارًا ولا درجة تُقارن بين الناس.","لا يُغني عن الفحص الطبي الذي يجريه الطبيب المختص.","الخطة موقّعة من المستفيد، ويمكنه تعديل أي جزء فيها.","يعمل الفريق على نسخة واحدة محدّثة من الخطة حتى لا تتناقص المعلومات."]', 'تقييم شامل ثم متابعة دورية', '[{"question":"هل ماتريكس بديل عن التقييم الطبي؟","answer":"لا. هو نظام تنظيم لمسار الإرشاد والتأهيل، ولا يُغني عن الفحص الطبي ولا عن قرار الطبيب المختص في أي مسألة طبية."},{"question":"ماذا لو لم تتوفر كل المعطيات؟","answer":"نبدأ بما يتوفر، ونحدّد الفجوات بصراحة. الخطة الناقصة الصريحة أنفع من تقدير يبدو كاملًا ويقود إلى قرار خاطئ."}]', 'برنامج ماتريكس للتقييم وخطط التعافي | سوار وعي', 'نظام منظّم يجمع معطيات الفحص الطبي والنفسي والاجتماعي في صورة واحدة، ويحوّلها إلى خطة تعافٍ عملية متفق عليها.', 1, true, true, '2026-10-04T11:58:23.398Z'::timestamptz, '2026-10-04T11:58:23.398Z'::timestamptz),
    ('cmutroqsq001guedc0cywod5o', 'PROGRAM', 'barmoj-minnesota', 'برنامج مينيسوتا ثلاثي الأضلاع', 'مسار متدرّج يقوم على ثلاثة أضلاع: علاج الأعراض الانسحابية، ثم تعديل السلوك فرديًا وجماعيًا، ثم إعادة التأهيل النفسي والاجتماعي والديني والترويحي.', '<p>التعافي عملية لها مراحل، وبرنامج مينيسوتا مبني على هذه الفكرة بوضوح: كل ضلع يعالج حاجة مختلفة، والانتقال بينها لا يقع بالتقويم وحده.</p>
<p>الضلع الأول هو علاج الأعراض الانسحابية، أي ما يحدث في الجسد والنفس عند التوقف، ويُدار بالتوازي مع الطبيب المختص ودوره في القرار الطبي. ويأتي بعده الضلع الثاني: تعديل السلوك الفردي والجماعي، حيث تفتح الجلسات الفردية المسار وتُعزّزه الجماعية. ثم يأتي الضلع الثالث: إعادة التأهيل النفسي والاجتماعي والديني والترويحي، حيث تُعاد صناعة العلاقات والدور الاجتماعي ومعنى اليوم ومعنى الوقت.</p>
<h2>كيف ينتقل المستفيد بين الأضلاع؟</h2>
<p>الانتقال يقوم على تقييم مستمر يقدّره الفريق مع المستفيد، لا على رقم أسابيع. من لم يجهز بعد يبقى حيث هو مع خطة تخدم استقراره، ومن جهز ينتقل ولو لم تمّ مدته الزمنية. وهذا هو جوهر البرنامج كله.</p>
<ul>
<li><strong>ضلع واحد في الوقت:</strong> لا نحمّل المستفيد ثلاثة أضلاع دفعة واحدة، لأن التشتّت في البداية يؤخر أكثر مما يسرّع.</li>
<li><strong>شرط الانتقال من الأول إلى الثاني:</strong> استقرار على مستوى الأعراض، مع قرار طبي مناسب من الطبيب المختص.</li>
<li><strong>شرط الانتقال من الثاني إلى الثالث:</strong> قدرة المستفيد على وصف سلوكه بوصفه سلوكًا، لا انفجارًا لا مفر له.</li>
<li><strong>أساس القرار:</strong> تقييم مسجّل مع المستفيد تشرح فيه أسباب الانتقال أو بقائه في ضلعه.</li>
<li><strong>إمكانية العودة:</strong> إذا حدث تراجع حاد نراجع الخطة كاملة، والعودة إلى ضلع سابق ليست رفضًا للتقدم.</li>
</ul>', 'Layers', NULL, NULL, 'من يحتاج إلى مسار منظّم يجمع بين التعامل مع الأعراض الجسدية وبين إعادة البناء النفسي والاجتماعي.', '[{"title":"الضلع الأول: الأعراض الانسحابية","description":"تهيئة نفسية، وشرح لما يمكن توقعه، ومرافقة المستفيد بالتنسيق مع الطبيب المختص."},{"title":"الضلع الثاني: تعديل السلوك","description":"عمل فردي وجماعي منظّم على الأنماط السلوكية ومحرّكاتها."},{"title":"الضلع الثالث: إعادة التأهيل","description":"بناء نفسي واجتماعي وديني وترويحي بحسب ما يختاره المستفيد ويناسبه."},{"title":"تقويم الانتقال","description":"تقييم دوري يحدّد جاهزية الانتقال بين الأضلاع وأسبابه."},{"title":"التثبيت والمتابعة","description":"متابعة دورية بعد استكمال الأضلاع الثلاثة."}]', '["مسار متدرّج يحترم الترتيب الذي يمر به الفرد فعليًا","تنسيق واضح بين الجوانب الطبية والنفسية والاجتماعية","مرونة في مدة كل ضلع بحسب الحالة لا بحسب التقويم","إعادة بناء شاملة للحياة بعد معالجة الأساس"]', '["فهم واضح لما يتطلبه كل ضلع وما يميّزه","استقرار في الأعراض الانسحابية بإشراف طبي","قدرة أكبر على ضبط المحفّزات والاستجابة لها","إعادة بناء شبكة علاقات ودور اجتماعي بعد التعافي"]', '["لا أحد يحدّد مدة البرنامج سلفًا، فالتقييم هو ما يحسم الانتقال.","الضلع الأول يحتاج تعاونًا مباشرًا مع الطبيب المختص ولا يبدأ قبل ذلك.","الإرشاد الديني والنشاط الترويحي في الضلع الثالث اختياريان بالكامل.","المشاركة الطوعية شرط أساسي، وللمستفيد حق الانسحاب في أي وقت."]', 'برنامج متعدد المراحل · بحسب الاستعداد', '[{"question":"هل ينتقل المستفيد بين الأضلاع في وقت محدد؟","answer":"ليس بالتقويم. الانتقال يقوم على تقدير الجاهزية مع المستفيد، وقد يستغرق الضلع الواحد وقتًا أطول أو أقصر بحسب الحالة والتقدم الملاحظ."},{"question":"ماذا لو عاد السلوك في ضلع متقدم؟","answer":"نراجع أولًا ما لم يستقر قبل الانتقال. كثيرًا ما يكون الخلل في الأساس لا في الإرادة، ويُعاد العمل على الضلع الأول قبل متابعة التقدم."},{"question":"هل البرنامج يغني عن جلسات المعالج؟","answer":"لا. الأضلاع الثلاثة تعمل مع الجلسات الفردية والجماعية ولا تحل محلها. المعالج هو من يقدّر متى ينتقل المستفيد وماذا يحتاج في كل ضلع."}]', 'برنامج مينيسوتا ثلاثي الأضلاع في التعافي | سوار وعي', 'مسار تعافٍ متدرّج يقوم على ثلاثة أضلاع: علاج الأعراض الانسحابية، وتعديل السلوك فرديًا وجماعيًا، وإعادة التأهيل النفسي والاجتماعي والديني والترويحي.', 2, true, true, '2026-10-04T11:58:23.402Z'::timestamptz, '2026-10-04T11:58:23.402Z'::timestamptz),
    ('cmutroqsu001huedc5ba1ct9l', 'PROGRAM', 'daz-altahassus', 'برامج إزالة التحسس من مثيرات الانتكاسة', 'خريطة المحفّزات، وتوسيع المسافة بين المحفّز والاستجابة، ووضعيات الانسحاب، وخطة انتكاسة مكتوبة قبل الحاجة إليها.', '<p>الانتكاسة غالبًا لا تأتي مفاجئة. تأتي بعد سلسلة خطوات يعرفها الشخص جيدًا: موقف، ثم شعور، ثم فكرة، ثم فعل. وحين نفهم هذه السلسلة تصير نقاط التداخل معها واضحة.</p>
<p>العمل هنا ليس على منع الرغبة، بل على توسيع المسافة بين لحظة ظهور المحفّز ولحظة الاستجابة. تلك المساحة هي المجال الحقيقي للتغيير، وهي أضيق ما يكون في بداية التعافي.</p>
<h2>ماذا يشمل البرنامج؟</h2>
<p>يُبنى البرنامج على واقع المستفيد لا على صورة عامة، فيُعاد تصميمه كلما تغيّر نمط الحياة أو تغيّرت محفّزاته. ولا يُتوقَّع منه أن يتخلّص من المحفّزات كلها، بل أن يتعلّم كيف يتعامل معها وهو أقوى.</p>
<ul>
<li><strong>خريطة المحفّزات:</strong> المواقف والأشخاص والأوقات والمشاعر التي تسبق الرغبة بالعودة.</li>
<li><strong>توسيع المسافة بين المحفّز والاستجابة:</strong> أدوات تُستعمل في تلك المساحة: التوقف، وتغيير المكان، والحديث مع شخص، وتأجيل القرار لا إلغاؤه.</li>
<li><strong>وضعيات الانسحاب:</strong> ما يفعله الشخص فعلًا عند مواجهة محفّز: أهرب أم أنكر أم أبرر أم أطلب المساعدة.</li>
<li><strong>خطة الانتكاسة:</strong> ماذا يفعل بالضبط بعد وقوعها، ومن يُبلَّغ في تلك اللحظة، وكيف تُدار نتيجتها.</li>
<li><strong>المواقف عالية الخطورة:</strong> كيف تُدار أو تُؤجَّل، وكيف يُخرج المستفيد نفسه منها حين لا الخيار له.</li>
</ul>', 'ShieldCheck', NULL, NULL, 'من مرّ بانتكاسة ويريد فهم سببها والبقاء أبعد عنها في المرة القادمة.', '[{"title":"حصر المحفّزات","description":"نرسم الخريطة الحقيقية من حياة المستفيد، لا الخريطة المثالية التي نرغب فيها."},{"title":"ترتيب الأولويات","description":"نبدأ بأخطر المحفّزات لأنها أكثرها تكرارًا في الانتكاسات السابقة."},{"title":"التدريب المتدرّج","description":"نواجه المحفّزات بدرجات متدرّجة، ولكل درجة أدوات التعامل الخاصة بها."},{"title":"كتابة خطة الانتكاسة","description":"نكتب مسبقًا ما سيُنفَّذ لو وقعت، ومن يُبلَّغ، وكيف تُدار النتيجة."}]', '["فهم شخصي لسبب الانتكاسة دون لوم أو اتهام","أدوات قابلة للتطبيق في اللحظة الحرجة","تقليل التعرّض المتعمد والمواقف الخطرة","خطة مكتوبة تحمي من قرارات لحظة الضعف"]', '["خريطة محفّزات مكتوبة ومحدّثة","قدرة على تسمية الشعور قبل أن يتحول إلى فعل","مساحة أطول بين المحفّز والسلوك","معرفة واضحة بما ينبغي فعله فور وقوع انتكاسة"]', '["لا يُتوقَّع من المستفيد التخلص من محفّزاته كلها، والهدف هو التعامل معها.","البرنامج مكمّل للخطة العلاجية لا بديل عنها.","قد تتغير خريطة المحفّزات بتغيّر الحياة، ولذلك تُراجع دوريًا.","كل ما يُقال في جلسات هذا البرنامج يبقى طيّة السرّية المهنية."]', 'برنامج قصير إلى متوسط', '[{"question":"هل الانتكاسة تحدث فجأة دون سبب؟","answer":"نادرًا ما تكون مفاجئة تمامًا. أغلب الحالات تسلسل معروف يسبقها: موقف ثم شعور ثم فكرة ثم فعل. البرنامج يبدأ من قراءة هذا التسلسل لا من اللوم."},{"question":"لماذا نكتب خطة الانتكاسة أصلًا؟","answer":"لأنها تُكتب في وقت هادئ وحين لا يوجد ضغط، فتكون جاهزة للتنفيذ في أسوأ اللحظات. ووقوعها لا يعني ضياع ما بُني، بل يعني أن الخطة تحتاج مراجعة."},{"question":"ما الفرق بين إزالة التحسس وتجنّب المواقف؟","answer":"التجنّب خطوة أولى مفيدة لكنه غير كافٍ على المدى الطويل. البرنامج يبدأ بالتجنّب عند الحاجة، ويعمل على بناء قدرة التعامل مع الموقف نفسه."}]', 'برامج إزالة التحسس من مثيرات الانتكاسة | سوار وعي', 'بناء خريطة محفّزات الانتكاسة، وتوسيع المسافة بين المحفّز والاستجابة، ووضعيات الانسحاب، وخطة انتكاسة مكتوبة مسبقًا.', 3, true, true, '2026-10-04T11:58:23.406Z'::timestamptz, '2026-10-04T11:58:23.406Z'::timestamptz),
    ('cmutroqsy001iuedcvshfw3cy', 'PROGRAM', 'barmoj-al-ithna-ashara-khatwa', 'برنامج الاثنتي عشرة خطوة', 'مسار تدريجي يقوم على الاعتراف ثم خطوات تبنى فوق ما قبلها، يُنفَّذ في مجموعة آمنة، وهو مكمّل للعلاج الطبي لا بديل عنه.', '<p>برنامج الاثنتي عشرة خطوة لم يُخترع في عيادة، بل نشأ في خبرة الجماعة نفسها. قوته في بساطته: كل خطوة تضيف شيئًا واحدًا فقط وتُبنى فوق ما سبقها، فلا يُطلب من أحد القفز فوق خطوة لم يجهّز نفسه لها.</p>
<h2>ما الذي يميّز منطق الخطوات؟</h2>
<p>يبدأ البرنامج بالاعتراف، أي قبول أن المشكلة واقعة وليست عيبًا في الخلق، ثم يتحرك خطوة خطوة: التسليم، وترتيب القرارات، وبناء علاقة بما يثبّت في الأيام الصعبة، والتوفيق، ثم الاستمرار. وأهم ما فيه ليس عدد الخطوات بل المجموعة.</p>
<p>حين يجتمع من يمر بتجربة مشابهة ويتحدثون بلغتهم الخاصة، ينخفض الخوف والذنب، وتصير المتابعة ممكنة بلا تكلّف. ونؤكد أمرين منذ البداية: أولًا أن البرنامج مكمّل للعلاج الطبي وليس بديلًا عنه، فلا يغني عن متابعة الطبيب المختص ولا عن الدواء إن وُجدت حاجة إليه. وثانيًا أنه لا يُشترط على أحد أن يتبنّى إطارًا روحيًا بعينه للمشاركة، فمن يجد في هذه المبادئ معنى يريحه يقرأها بذلك، ومن لا يجد فيه يشارك في خطوتها العملية كما هي.</p>
<ul>
<li><strong>الاعتراف:</strong> قبول أن المشكلة واقعة، وأن الإنكار نفسه جزء من المشكلة لا مخرج منها.</li>
<li><strong>التسليم:</strong> التوقف عن محاربة الواقع، وتحمّل المسئولية من غير لوم للذات ولا تبرير مستمر.</li>
<li><strong>قرارات الحياة:</strong> ترتيب ما يهم فعلًا، بدل ترتيب ما يبدو مهمًا في الظاهر فقط.</li>
<li><strong>ما يثبّت في الأيام الصعبة:</strong> إيمان أو معنى أو قيمة أو شخص، بحسب ما يختاره المستفيد بلا إلزام.</li>
<li><strong>ما بعد البرنامج:</strong> خطة مكتوبة لاستمرار ما بُني، ومراجعة دورية للوضع على المدى الطويل.</li>
</ul>', 'Footprints', NULL, NULL, 'من يقبل وجود مشكلة ويرضّ مسارًا يقوم على المرافقة الجماعية والتدرّج الهادئ.', '[{"title":"الاعتراف والتسليم","description":"قبول الواقع بدل الإنكار، وهو شرط البداية في البرنامج."},{"title":"الانتقال من العزلة","description":"الالتحاق بمجموعة آمنة يشاركها من يمر بتجربة مشابهة."},{"title":"الخطوات المتدرجة","description":"بناء التغيّر خطوة خطوة، دون قفزة واحدة كبيرة في البداية."},{"title":"المتابعة","description":"المحافظة على ما بُني، ومراجعة الخطر في اللقاءات الدورية."}]', '["تدرّج يخفف ثقل البداية ويجعل الخطوة الأولى ممكنة","تقليل الوصم والذنب في مجموعة تفهم من يمر بالتجربة نفسها","المجموعة كمسؤولية يومية تدعم الاستمرار","خطة مكتوبة ومنهج واضح بعد انتهاء البرنامج"]', '["قرار التوقف مبني على فهم لا على إجبار","قدرة على العودة إلى المجموعة عند الحاجة","مسؤوليات يومية تسهّل الاستمرار","خطة مكتوبة لمراجعة ما بعد البرنامج"]', '["البرنامج مكمّل للرعاية الطبية والإرشادية وليس بديلًا عن أي منها.","لا يُشترط أي إطار روحي للمشاركة، والقرار في ذلك للمستفيد وحده.","لا يُسرَّع البرنامج بإتمام خطوات لم يجهّز لها المستفيد.","سرّية اللقاءات أساس ثقة المجموعة، وما يُقال داخلها لا يخرج منها."]', 'مجموعات أسبوعية', '[{"question":"هل يمكن استخدام البرنامج مع إيقاف الدواء؟","answer":"لا يُقرّر ذلك إلا الطبيب المختص. نحن ننسّق مع الطبيب ولا نُقدّر حاجة أحد طبية، والتوقف المفاجئ عن الدواء قد يكون أخطر من الاستمرار."},{"question":"هل يلزم الإيمان بالمبادئ الروحية للمشاركة؟","answer":"لا. الإطار الروحي اختياري تمامًا، ونوضّح ذلك منذ البداية. من لم يجد في هذه المبادئ ما يستريح به يشارك في خطواتها العملية."},{"question":"هل يناسب من ليس لديه ارتباط بمادة بعينها؟","answer":"قد يناسبه، لأن منطق الخطوات يتعلق بالسلوك ومحرّكاته والدور لا بمادة بعينها. ويُحدَّد ذلك بعد التقييم الأولي."}]', 'برنامج الاثنتي عشرة خطوة في التعافي | سوار وعي', 'مسار تدريجي يقوم على الاعتراف وخطوات مبنية فوق ما قبلها، يُنفَّذ في مجموعة آمنة، ويُكمّل العلاج الطبي ولا يحل محله.', 4, true, false, '2026-10-04T11:58:23.410Z'::timestamptz, '2026-10-04T11:58:23.410Z'::timestamptz),
    ('cmutroqt2001juedcoim7dvyr', 'PROGRAM', 'barmoj-al-daa-al-ijtimaai', 'برامج الدعم الاجتماعي', 'مقاومة العزلة، وبناء شبكة دعم حقيقية، وأدوار وأنشطة تمنح اليوم معنى، لأن العزلة كثيرًا ما تسبق الانتكاسة.', '<p>من يملك سببًا يستيقظ من أجله أقل عرضة للانتكاسة. الدعم الاجتماعي هنا ليس ترفيهًا، بل تدخل عملي في إعادة البناء.</p>
<p>الانتكاسة كثيرًا ما تسبقها لحظة ثمرة: يوم بلا هدف، وبيت لا فيه أحد، وخلاف أو شعور بالرفض. والدعم الاجتماعي يعالج هذه الثغرة قبل أن تتحول إلى قرار.</p>
<h2>ماذا نعني بالدعم الاجتماعي؟</h2>
<p>نحن لا نكتفي بجلسات. نبني شبكة من أشخاص وأنشطة ومسؤوليات تبدأ من داخل المركز ثم تتسع تدريجيًا إلى الحياة الحقيقية، وبوتيرة يريحها المستفيد نفسه.</p>
<ul>
<li><strong>شبكة أشخاص:</strong> علاقات مبنية على الصدق لا على المصلحة، نعرف فيها من نقبله ومن يحتاج بعده.</li>
<li><strong>أنشطة جماعية:</strong> رياضة وورش وهوائيات وعمل تطوعي تمنح اليوم معنى ومسؤولية محسوسة.</li>
<li><strong>مسؤوليات صغيرة:</strong> دور داخل المجموعة يكسب المستفيد شعور الانتماء والاعتماد، لا شعور الشكر.</li>
<li><strong>مهارات اجتماعية:</strong> كيف تُبنى العلاقة، وكيف تُحفظ، وكيف يُتعامل مع الخلاف دون قطع.</li>
<li><strong>معالجة العزلة:</strong> لأنها تعمل ضد مسار التعافي حتى حين لا يراها المستفيد خطرًا.</li>
</ul>', 'Handshake', NULL, NULL, 'من يتعافى وحيدًا، أو قطع علاقاته، أو يحتاج إلى بيئة اجتماعية أكثر بنية وتنظيمًا.', '[{"title":"تقييم شبكة الدعم","description":"من موجود في حياة المستفيد اليوم؟ ومن يمكن إضافته لاحقًا؟"},{"title":"الالتحاق بمجموعة","description":"نبدأ بمكان آمن يمكن الانسحاب منه في أي وقت دون تبرير."},{"title":"أخذ دور","description":"مسؤولية صغيرة داخل المجموعة والالتزام بها حتى نهاية الفترة."},{"title":"التوسيع التدريجي","description":"بناء علاقات خارج المركز خطوة بخطوة وبشروط تحفظ كرامته."}]', '["شبكة دعم حقيقية بدل العزلة","أدوار تمنح اليوم معنى ومسؤولية","ممارسة نشاط منتظم مع أشخاص آخرين","مهارات بناء العلاقات والتعامل مع الخلاف"]', '["دور اجتماعي واضح داخل المجموعة","نشاط أسبوعي منتظم لا موافق عليه فقط","قدرة على طلب الدعم في وقتها لا في الأسوأ","توسيع تدريجي لعلاقات خارج المركز"]', '["الشبكة تُبنى بالوتيرة التي يريحها المستفيد لا بسرعة مفروضة.","قد لا تكون كل العلاقات مناسبة، ولذلك نراقب أثر كل علاقة في مسار التعافي.","هذا العمل لا يغني عن الخطة العلاجية بل يسندها."]', 'أنشطة ولقاءات أسبوعية', '[{"question":"هل يكفي الانضمام إلى مجموعة أسبوعية؟","answer":"قد تكون بداية مفيدة، لكنها لا تصنع شبكة دعم بمفردها. الشبكة تحتاج أيضًا علاقات خارج المركز ومسؤوليات حقيقية داخل المجموعة."},{"question":"كيف أعرف أن العلاقة مناسبة؟","answer":"بأثرها في استقرارك لا بمتعة اللقاء وحدها. العلاقة التي تدفعك لإخفاء ما تمر به ليست شبكة دعم مهما بدت دافئة."}]', 'برامج الدعم الاجتماعي في التعافي | سوار وعي', 'برامج تدعم المستفيد وتقاوم العزلة، وتبني شبكة دعم حقيقية، وتفتح له أدوارًا وأنشطة تمنح اليوم معنى ومسؤولية.', 5, true, false, '2026-10-04T11:58:23.414Z'::timestamptz, '2026-10-04T11:58:23.414Z'::timestamptz),
    ('cmutroqt6001kuedclmdz7jre', 'PROGRAM', 'barmoj-al-ilaj-bi-al-fann', 'برامج العلاج بالفن', 'الرسم والتلوين والنحت والأداء، قناة تعبيرية غير لفظية تكشف ما يصعب قوله وتُدرّب على ضبط الانفعال.', '<p>الفن هنا ليس هواية جميلة. كل جلسة فنية تنتهي بفهم: ماذا أظهر هذا اللون؟ لماذا هذا الشكل؟ وما الذي قالته الصورة ولم يقله اللسان؟</p>
<p>العلاج بالفن لا يستبدل الحوار، بل يفتح قناة أخرى حين يعجز اللسان. ولذلك يُقدَّم في فضاء آمن يحفظ فيه المستفيد كرامته كاملة، ولا يُطلب منه أن يكون فنانًا ولا أن يكون جيدًا.</p>
<h2>ما الذي يقدّمه العلاج بالفن؟</h2>
<p>يُنفَّذ البرنامج في جلسات أسبوعية منتظمة، ويُربط مضمونها بما نتناوله في الجلسات العلاجية نفسها، فيغني الخطاب بدل أن ينافسه.</p>
<ul>
<li><strong>قناة بديلة:</strong> حين تعجز الكلمات، يبقى اللون والشكل يقولان ما لا يُقال، دون خوف من الحكم على الصياغة.</li>
<li><strong>ضبط الانفعال:</strong> تحويل الطاقة إلى أثر ملموس على الورق، وهي في جوهرها مهارة ضبط انفعال.</li>
<li><strong>إعادة فهم الذات:</strong> يرى الفرد في أعماله بعد فترة ما لا يراه في كلامه المباشر.</li>
<li><strong>إنجاز ملموس:</strong> كل عمل منتهٍ يمنح شعورًا بالإنجاز، وهو نقيض ما يبحث عنه السلوك المزعج.</li>
</ul>', 'Palette', NULL, NULL, 'من يجد التعبير بالكلمات صعبًا، ومن يريد أداة عملية في ضبط مشاعره.', '[{"title":"تهيئة فضاء آمن","description":"طمأنة وتعريف بقواعد المكان: لا نقد للأعمال ولا تقييم لها."},{"title":"العمل الفني","description":"تعبير حر دون تصحيح أو توجيه يُملى على المستفيد."},{"title":"المراجعة","description":"ماذا ظهر في العمل؟ وما الذي يعنيه لصاحبه؟"},{"title":"الربط بالعلاج","description":"مناقشة ما ظهر داخل الجلسات العلاجية وربطه بالسياق."}]', '["قناة تعبير تناسب من يصعب عليه الكلام","تنمية مهارة ضبط الانفعال","تحسين المزاج وجودة النوم","إنجاز ملموس يناهض ما يبحث عنه السلوك المزعج"]', '["قدرة أفضل على التعبير عن المشاعر","استقرار في المزاج العام","ممارسة فنية منتظمة","فهم أعمق لأنماط السلوك ودوافعها"]', '["لا تُعرض أي عمل على أحد دون موافقة صريحة من صاحبه.","لا يُقاس العمل الفني بجماله بل بما يوصل إليه صاحبه.","البرنامج مكمّل للعمل العلاجي، ولا يُغني عنه."]', 'جلسات أسبوعية · ٦٠ دقيقة', '[{"question":"لست فنانًا، هل يناسبني؟","answer":"الفن هنا ليس مهارة. لا خبرة سابقة مطلوبة، ولا يُطلب من المستفيد أن يكون جيدًا، بل حاضرًا ومتاحًا لتعبيره."},{"question":"هل العلاج بالفن بديل عن الجلسات؟","answer":"لا. هو مكمّل ممتاز، ويعمل بشكل أفضل حين يقترن بالخطة العلاجية ويقرن بما يطرده في الجلسات."}]', 'برامج العلاج بالفن في التعافي | سوار وعي', 'العلاج بالفن قناة تعبير غير لفظية تكشف ما يصعب قوله، وتُدرّب على ضبط الانفعال، وتُدار ضمن خطة تعافٍ متكاملة.', 6, true, false, '2026-10-04T11:58:23.418Z'::timestamptz, '2026-10-04T11:58:23.418Z'::timestamptz),
    ('cmutroqta001luedchd7hyvus', 'PROGRAM', 'al-ilaj-bi-al-riada', 'العلاج بالرياضة', 'نشاط بدني منظّم يبني الانضباط ويحسّن المزاج وجودة النوم، ويبدأ من مستوى يناسب كل فرد بحسب تقييمه.', '<p>الرياضة ليست ترفًا في خطة التعافي. الجسم المتعب يحتاج حركة، والنفس المنهك يحتاج نجاحًا يتكرر.</p>
<p>النشاط البدني قد يفيد في تحسين جودة النوم وخفض التوتر، وتشير تجارب كثيرة إلى أثره في المزاج. وهو مع ذلك دعم داخل الخطة لا علاج بذاته، ويُقدَّر أثره بحسب استجابة كل فرد.</p>
<h2>كيف ننفّذ البرنامج؟</h2>
<p>لا نضع أحدًا في برنامج جاهز للجميع. نبدأ بتقييم لمستوى اللياقة والحالة الصحية، ثم نحدّد النشاط المناسب، ثم نراجع الاستجابة دوريًا ونعدّل بحسبها.</p>
<ul>
<li><strong>تقييم البداية:</strong> مستوى اللياقة والحالة الصحية وأي قيود حركية، بالتشاور مع الطبيب عند وجود سبب طبي.</li>
<li><strong>خطة متدرجة:</strong> نبدأ بمستوى مريح ونزيد ببطء، فالإفراط الزائد في البداية لا ينفع أحدًا.</li>
<li><strong>نشاط عملي:</strong> مشي منظّم، وتمارين مقاومة خفيفة، وأنشطة رياضية جماعية هادئة بحسب التقييم.</li>
<li><strong>متابعة وتعديل:</strong> نقيس التحسّن ونعدّل الخطة كلما احتجنا، ومع تحسّن اللياقة يتوسّع النشاط تدريجيًا.</li>
</ul>', 'Dumbbell', NULL, NULL, 'كل من يحتاج إلى حركة منتظمة كدعم أساسي، وخصوصًا في المراحل الأولى من التعافي.', '[{"title":"تقييم اللياقة والحالة الصحية","description":"نعرف البداية الفعلية وما يحتمله الجسم الآن قبل أي جهد."},{"title":"بناء خطة متدرجة","description":"نحدّد النشاط والحجم والتكرار بما يناسب الحالة."},{"title":"التنفيذ المنتظم","description":"حصص في المركز وتمرين منزلي موثّق عند الحاجة."},{"title":"المتابعة","description":"قياس التحسّن وتعديل الخطة على فترات محددة."}]', '["تحسين جودة النوم والشعور العام بالحيوية","خفض التوتر وتحسين المزاج","بناء انضباط يناهض ما يبحث عنه السلوك المزعج","فرص لقاء صحي مع أشخاص آخرين"]', '["نشاط بدني أسبوعي منتظم","استقرار في جودة النوم","تحسن في القدرة على ضبط الانفعال","توسيع شبكة العلاقات خارج المركز"]', '["لا يُبدأ النشاط البدني قبل التأكد من مناسبة الحالة الصحية، ويُنسَّق مع الطبيب عند وجود سبب طبي.","من لديه قيود حركية يُخصَّص له برنامج مناسب بدل برنامج موحّد للجميع.","الرياضة دعم للخطة العلاجية وليست بديلًا عنها.","الجهد المعتدل أكثر استفادة من الإرهاق في البداية."]', '٣ إلى ٤ حصص أسبوعيًا', '[{"question":"هل أحتاج إلى رياضة سابقة؟","answer":"لا. نبدأ من مستوى منخفض ونبنيه ببطء. الأهم في البداية هو الانتظام لا الشدة، ومن أراد أن يبدأ بمستوى أعلى نعرض عليه التقييم أولًا."},{"question":"هل تكفي المشي وحده؟","answer":"غالبًا تكفي كبداية مفيدة، ويُحدَّد ذلك بحسب تقييمك وحالتك الصحية. ويمكن أن نضيف تمارين مقاومة لاحقًا بحسب ما يسمح به تقييمك."}]', 'العلاج بالرياضة في تعافي الإدمان | سوار وعي', 'نشاط بدني منظّم يبدأ من مستوى يناسب كل فرد، يدعم تحسين النوم والمزاج ويبني انضباطًا ضمن خطة تعافٍ متكاملة.', 7, true, false, '2026-10-04T11:58:23.422Z'::timestamptz, '2026-10-04T11:58:23.422Z'::timestamptz),
    ('cmutroqte001muedc2t1vcx96', 'PROGRAM', 'tanishit-al-dafa', 'برامج تنشيط الدافعية من خلال تتبع مراحل التغيير', 'مساعدة المستفيد على رؤية موقعه الحقيقي ضمن مراحل التغيير، وعلى صياغة خطوة واحدة واقعية تناسب مرحلته.', '<p>أكثر ما يعيق التغيير ليس نقص المعرفة، بل الجهل بالموقع. من يعرف أنه في مرحلة ما قبل التغيير يتصرّف بمنطق، ومن يظن نفسه في مرحلة الإعداد لا يلوم نفسه على عدم البدء.</p>
<p>نعتمد نموذجًا تطبيقيًا مفهومًا لغير المتخصصين، يقسم المسار إلى مراحل لكل منها خصائصها وأدواتها ومتطلباتها. والانتقال بينها ليس قفزة بل تحوّل.</p>
<h2>مراحل التغيير</h2>
<p>لكل مرحلة ما يناسبها من الطلب. وفي مرحلة ما قبل التغيير لا نطلب التزامًا كبيرًا بل نفتح باب الحوار، وفي مرحلة التغيير نركز على الاستدامة، لأن الثبات هو ما يصعب أكثر من البداية.</p>
<ul>
<li><strong>ما قبل التغيير:</strong> وصف صادق للواقع بلا تجميل ولا قسوة، وبناء ثقة تسمح بالكلام أصلًا.</li>
<li><strong>التفكير في التغيير:</strong> إظهار الفارق بين الوضع الحالي وما يتمناه المستفيد، دون محاسبة ولا ضغط.</li>
<li><strong>الاستعداد:</strong> صياغة خطوة صغيرة محددة مع موعد واضح للبدء.</li>
<li><strong>التغيير:</strong> التنفيذ ومتابعة يوميات السلوك، ومعالجة الانتكاسة بوصفها معلومة لا هزيمة.</li>
<li><strong>الثبات:</strong> تثبيت ما بُني، والعودة إلى التقييم الدوري كلما تغيّرت الظروف.</li>
</ul>', 'Target', NULL, NULL, 'من يتردد في اتخاذ قرار التغيير، أو تبقّى في مرحلة تتكرر فيها الدورات نفسها.', '[{"title":"تحديد المرحلة","description":"نصف المرحلة الحالية بدقة وصدق، دون تجميل ولا تقويم."},{"title":"التوعية","description":"نفهم خصائص كل مرحلة وما تحتاجه في هذه المرحلة بالذات."},{"title":"الخطوة الواحدة","description":"نتفق على خطوة واحدة صغيرة وواقعية لها موعد بدء."},{"title":"المتابعة","description":"نراجع الموقف في الجلسات التالية ونصحّح ما يحتاج تصحيحًا."}]', '["رؤية صادقة لموقعك من المسار","طلب واقعي يناسب مرحلتك لا ما هو مثالي","تقليل الإحساس بالذنب والإحباط","خطوة واضحة لها موعد تنفيذ محدد"]', '["موقع واضح ضمن مراحل التغيير","خطوة أولى محددة وموعد بدء معلوم","سجل متابعة بسيط لملاحظات التقدم","مراجعة دورية تعالج تعثّر الخطوات"]', '["تحديد المرحلة تقدير مهني قائم على الملاحظة والحوار، وليس حكمًا على الشخص.","الورشة أداة توعية قصيرة لا تُغني عن الخطة العلاجية الكاملة.","قد يختلف تقييم الموقع عن تقدير المستفيد لنفسه، ويُناقش ذلك دون إحراج."]', 'ورشات قصيرة · ٩٠ دقيقة', '[{"question":"كيف أعرف أنني في مرحلة معينة؟","answer":"بمقارنة ما تعيشه بما تتطلبه كل مرحلة. من ما زال يقنع نفسه بعدم وجود مشكلة لم يبدأ التفكير في التغيير بعد، ومن يفكر دون أن يقرر فهو في مرحلة الاستعداد."},{"question":"لماذا تبدو خطوتي الأولى صغيرة؟","answer":"لأن الخطوات الصغيرة هي التي تُنفَّذ فعلًا في بداية الطريق، والخطوة الكبيرة وحدها تبقى نية. نراجعها بعد مدة قصيرة ونبني عليها."}]', 'تنشيط الدافعية عبر مراحل التغيير | سوار وعي', 'برامج تساعد المستفيد على تحديد موقعه من مراحل التغيير، وصياغة خطوة واقعية، والمتابعة المنتظمة دون لوم أو ضغط.', 8, true, false, '2026-10-04T11:58:23.426Z'::timestamptz, '2026-10-04T11:58:23.426Z'::timestamptz),
    ('cmutroqti001nuedc96dv88dc', 'PROGRAM', 'barmojat-dabb-al-suluk', 'البرامج العلاجية والإرشادية لضبط السلوك', 'برامج مصممة لضبط سلوك محدد بدل التوجيه العام: تعريف دقيق للسلوك، وتحليل وظيفته، وبناء بديل، وتدريب عملي عليه.', '<p>أحيانًا لا يحتاج الشخص إلى خطة حياة جديدة، بل إلى ضبط سلوك واحد محدد يزعجه أو يزعج من حوله. هنا يأتي دور البرامج العلاجية والإرشادية لضبط السلوك.</p>
<p>الفكرة بسيطة في ظاهرها وصعبة في تطبيقها، فكثير مما يفشل يعود إلى عمومية الهدف. لذلك نعمل دائمًا على سلوك محدد ومقيس ومرتبط بظرف معروف.</p>
<h2>كيف يعمل هذا النوع من البرامج؟</h2>
<p>لا نتحدث عن سلوك سيئ بشكل عام، بل نحدّد السلوك ومتى يحدث ومع من، ثم نفحص ما الذي يحققه هذا السلوك فعلًا، ثم نبني بديلًا وأدوات دعم تُستعمل في الموقف نفسه.</p>
<ul>
<li><strong>تحديد السلوك بدقة:</strong> وصف محدّد بدل التعميم، وبدل الحكم على الشخص أو على تمييزه.</li>
<li><strong>تحليل الوظيفة:</strong> ما الذي يحققه هذا السلوك؟ راحة، أم انتباه، أم تجنّب موقف، أم وسيلة تواصل؟</li>
<li><strong>بناء البديل:</strong> سلوك آخر يحقق الوظيفة نفسها بأقل ضرر ممكن.</li>
<li><strong>التدريب العملي:</strong> تمثيل المواقف والتدرب على الردود المطلوبة في بيئة آمنة.</li>
<li><strong>التعزيز الإيجابي:</strong> الانتباه لما يتحسن، لا تكرار الحديث عمّا لم يتحسن.</li>
</ul>', 'Scale', NULL, NULL, 'من يريد تغييرًا محددًا وملموسًا في سلوك بعينه يزعجه أو يزعج من حوله.', '[{"title":"تحديد السلوك","description":"وصف دقيق ومحدّد للسلوك ومتى يحدث ومع من."},{"title":"تحليل الوظيفة","description":"نفهم ما يحققه السلوك وما الذي يحميه من التوقف."},{"title":"بناء البديل","description":"نصمم سلوكًا بديلًا قابلًا للتنفيذ في الواقع لا في الجلسة فقط."},{"title":"التدريب والتعزيز","description":"نمارس السلوك الجديد ونثبّته بالنتائج التي يتفق عليها المستفيد."}]', '["هدف محدد وقابل للقياس بدل التوجيه العام","فهم دقيق لما يحققه السلوك المزعج","أدوات بديلة جاهزة للاستخدام في الموقف نفسه","نتائج ملموسة تُقاس ثم تُعزَّز"]', '["تعريف مكتوب للسلوك المستهدف","أدوات بديلة جاهزة للمواقف المتكررة","انخفاض ملموس في تكرار السلوك","تقليل الأثر على العلاقات المحيطة"]', '["البرنامج يخدم هدفًا محددًا ولا يشمل مسار التعافي كله.","قد تكون الحالات انفعالًا غاضبًا أو سلوكًا عدوانيًا أو سلوكًا متكررًا في المدرسة أو العمل، ويُحدَّد ذلك بعد التقييم.","لا نستخدم لغة الوصم، ونتحدث عن سلوك محدد في ظرف محدد.","الانتكاسة أثناء البرنامج تُعامل كإشارة على تعديل الخطة لا كنهاية الطريق."]', 'برامج متوسطة · ٦ إلى ١٠ أسابيع', '[{"question":"هل يناسب من ليس لديه ارتباط بمادة بعينها؟","answer":"قد يناسبه، فالبرنامج يخصّ السلوك ومحرّكاته وهو قابل للتطبيق على أنماط سلوكية متعددة. ويُحدَّد ذلك بعد التقييم الأولي."},{"question":"كيف نعرف أن السلوك تحسّن؟","answer":"نضع تعريفًا مكتوبًا للسلوك المستهدف ونتفق على مؤشرات بسيطة، ثم نراجعها دوريًا. وما لا يمكن قياسه يبقى انطباعات ذائبة."}]', 'برامج ضبط السلوك العلاجية والإرشادية | سوار وعي', 'برامج علاجية وإرشادية لضبط سلوك محدد: تعريف دقيق للسلوك، وتحليل وظيفته، وبناء بديل عملي، ومتابعة دورية.', 9, true, false, '2026-10-04T11:58:23.430Z'::timestamptz, '2026-10-04T11:58:23.430Z'::timestamptz),
    ('cmutroqtn001ouedch7x2nbv7', 'PROTOCOL', 'brotokol-al-ilaj-al-dawai', 'بروتوكول العلاج الدوائي', 'لا نصف دواءً ولا نحدّد جرعة، فذلك من اختصاص الطبيب المختص وحده. دورنا التثقيف والالتزام والتنسيق مع الطبيب والدعم النفسي المصاحب.', '<h2>توضيح جوهري</h2>
<p><strong>نحن لا نصف دواءً ولا نحدّد جرعة في أي مرحلة.</strong> العلاج الدوائي والقرار الدوائي من اختصاص الطبيب المختص وحده، بعد فحوصه وتقييمه. وما يلي هو نطاق عملنا في هذا البروتوكول، وهو محدود وواضح لا يُتجاوز.</p>
<p>دورنا يقوم على خمس وظائف: التثقيف، ومساعدة المستفيد على الالتزام بالبروتوكول الطبي كما حدّده الطبيب، والتنسيق مع الطبيب، وتقديم الدعم النفسي المصاحب، والتصدي للتحرّش عن التوقف. والتوقف عن الدواء قرار طبي في كل الأحوال، وقد يوقفه الطبيب لأنه لم يعد مناسبًا، وهذا لا يعني ضياع ما بُني.</p>
<ul>
<li><strong>التثقيف:</strong> شرح ما هو الدواء ولماذا وُصف، والآثار المتوقعة، بأسلوب يفهمه المستفيد دون إخفاء آثار يجب معرفتها ودون تهويل ما لا يستدعي الهلع.</li>
<li><strong>الالتزام بالبروتوكول الطبي:</strong> توضيح أهمية المواعيد وتثبيت موعد الدواء، وأن التوقف المفاجئ قد يكون أخطر من الاستمرار. ويبقى التعديل والقرار بيد الطبيب وحده.</li>
<li><strong>التنسيق مع الطبيب:</strong> نقل ملاحظات المستفيد ونتائج المتابعة إلى الطبيب، وتوصيل تعليمات الطبيب إليه بوضوح، والتعاون مع الجهة التي تُنفّذ المتابعة الطبية.</li>
<li><strong>الدعم النفسي المصاحب:</strong> كثير من الجلسات تتوقف في بداية مرحلة العلاج الدوائي، وهذا الجانب له أثر واضح في استمرار المستفيد وتحمّله.</li>
<li><strong>التصدي للتحرّش عن التوقف:</strong> دعم من يريد إيقاف الدواء لمجرد أنه بدأ يشعر بالتحسن، أو يظن أنه لم يعد بحاجة إليه، دون أن نتخذ قرارًا في الموضوع.</li>
</ul>
<p>لا يبدأ أيٌّ من هذه المسؤوليات إلا بعد تقييم طبي من جهة مختصة، ولا نتخذ قرارًا دوائيًا في أي مرحلة ولا نضغط على الطبيب لتغيير رأيه. وهذا الفصل ليس شكلًا في الاتفاق، بل هو ما يحمي المستفيد.</p>', 'Stethoscope', NULL, NULL, 'من يلجأ إلى دواء ضمن خطة علاجية متكاملة، ومن يحتاج إلى دعم نفسي مصاحب في أثناء ذلك.', '[]', '[]', '["فهم أوضح للدواء ولماذا وُصف به","انتظام أكبر في المواعيد وفي أخذه بموعده","تنسيق مسجّل ومستمر مع الطبيب المعالج","تراجع التحرّش عن التوقف عند الشعور بالتحسن"]', '["الوصفة والجرعة ومدة العلاج من الطبيب المختص حصريًا.","نلتزم بتعليمات الطبيب ولا نعدّلها ولا نقترح بديلًا من تلقائنا.","لا نقدّم خدمة البروتوكول الدوائي دون تقرير طبي معتمد ومرافقة طبية.","قرار البدء أو التوقف عن الدواء يبقى قرارًا طبيًا في كل الأحوال."]', 'مدة يحدّدها الطبيب المختص', '[{"question":"هل أستطيع سؤال موظفكم عن جرعة دوائي؟","answer":"لا. لا يصف أحد في المركز دواءً ولا يحدّد جرعة ولو سؤالًا. التوجيه الصحيح هو الطبيب المعالج، ونحن نساعدك على الوصول إليه والتنسيق معه."},{"question":"ماذا لو شعرت بالتحسن وتريد إيقاف الدواء؟","answer":"لا توقف من تلقاء نفسك. حالات كثيرة تتحول إلى أخطَر بسبب التوقف المفاجئ. أخبر طبيبك، ونعمل معك في جلسة تعالج هذا التحرّش بالكلام والأدوات."},{"question":"هل توفّرون الأدوية في المركز؟","answer":"لا. لا صيدلية لدينا ولا صرف لدينا. كل ما يتعلق بالدواء يمر عبر الطبيب المعالج، ودورنا التثقيف والتنسيق والمتابعة."}]', 'بروتوكول العلاج الدوائي والتنسيق الطبي | سوار وعي', 'لا يصف مركزنا دواءً ولا يحدّد جرعات. دورنا التثقيف والالتزام بالبروتوكول الطبي والتنسيق مع الطبيب والدعم النفسي المصاحب.', 1, true, false, '2026-10-04T11:58:23.435Z'::timestamptz, '2026-10-04T11:58:23.435Z'::timestamptz),
    ('cmutroqtr001puedco6bfie5l', 'PROTOCOL', 'brotokol-ilm-al-nafs-al-ikliniki', 'بروتوكول علم النفس الإكلينيكي والبرامج العلاجية', 'منهجية عمل معلنة تبدأ بالتقييم، وتشارك في التشخيص النفسي دون إصداره، ثم صياغة الحالة المفهومية والخطة العلاجية وما بعد التقييم.', '<p>علم النفس الإكلينيكي هو المنهج الذي يربط الفهم العلمي للحالة بالتدخل الفعلي. نعمل به وفق منهجية معلنة نستطيع تفسيرها للمستفيد في أي وقت، ولهذا نكتب ما نتفق عليه ونرجع إليه.</p>
<h2>مراحل العمل</h2>
<p>لكل مرحلة مخرج واضح، ولا ننتقل إلى ما بعدها دون استيفاء ما قبلها. والتسجيل المنتظم هو ما يجعل المراجعة ممكنة ومفهومة، لا مجرد انطباعات متفرقة.</p>
<ul>
<li><strong>التقييم والتشخيص النفسي:</strong> مقابلة سردية منظّمة، ومراجعة التاريخ الطبي والنفسي، وملاحظة السلوك وأنماطه. ويوضع التشخيص وفق معايير تصنيف مهنية، ويبقى القرار داخل التخصص الطبي: نحن نشارك في التقييم ولا نصدر التشخيص النهائي.</li>
<li><strong>صياغة الحالة المفهومية:</strong> فرضية تفسيرية تربط الأعراض بالسياق ولحظة حياة المستفيد، وتُبنى عليها الخطة وتُختبر أثناء العمل.</li>
<li><strong>الخطة العلاجية:</strong> أهداف قابلة للقياس، وعدد الجلسات وتوقيتها، والمنهاج المختار، ومؤشرات التقدم المتفق عليها.</li>
<li><strong>التنفيذ والتقييم الدوري:</strong> قياس الأثر بأدوات مناسبة، وتعديل الخطة عند الحاجة بدل الاستمرار بها بحجة الانتظام.</li>
<li><strong>ما بعد التقييم:</strong> تقييم ختامي وتوصيات لاستمرار الرعاية أو لتحويل الحالة إلى جهة مختصة أخرى عند الحاجة.</li>
</ul>
<p>والسرّية جزء أصيل من هذه المنهجية لا إضافة إليها: الملاحظات تُحفظ مشفّرة في النظام، ولا يطّلع عليها إلا المختصون المخوّلون، ولا تُشارك مع أي طرف خارجي دون موافقة مستنيرة من المستفيد.</p>', 'FileHeart', NULL, NULL, 'المستفيدون الذين يحتاجون تقييمًا سرديًا منظمًا وتدخلًا علاجيًا مسندًا إلى منهجية واضحة، ومن يحتاج تحويلًا إلى تخصص آخر.', '[]', '[]', '["خطة علاجية مكتوبة يفهمها المستفيد","تقييم دوري مسجّل يوضح ما الذي تغيّر فعلًا","معرفة واضحة بمسار الحالة وما الذي يتطلبه","تقرير منظم عند الحاجة إلى تحويل الحالة"]', '["نشارك في التقييم ولا نصدر التشخيص النفسي النهائي، فذلك قرار التخصص الطبي.","الملاحظات تُحفظ مشفّرة، والاطلاع عليها مقصور على المختصين المخوّلين.","أي مشاركة في المعلومات تتطلب موافقة المستفيد المستنيرة.","الخطة تُراجع دوريًا وتُعدّل بحسب الاستجابة، لا بحسب مرور التقويم."]', 'متابعة بحسب حالة كل مستفيد', '[{"question":"هل أستطيع معرفة تشخيصي من سجل الملف؟","answer":"التشخيص من قرار التخصص الطبي، وما يهمك الآن هو فهم الخطة وما تقتضيه. ونشرح لك ذلك بلغتك في الجلسة بدل المصطلحات وحدها."},{"question":"ماذا لو احتاجت تخصصًا آخر؟","answer":"قد يُحوَّل الطلب إلى جهة مختصة أخرى. ونمنحك تقريرًا منظمًا يشرح ما وصلنا إليه، ونُكمل التنسيق مع الجهة المستقبلة إذا وافقت على ذلك."}]', 'بروتوكول علم النفس الإكلينيكي والبرامج العلاجية | سوار وعي', 'منهجية معلنة تبدأ بالتقييم وتشارك في التشخيص النفسي دون إصداره، ثم تصوغ الحالة المفهومية والخطة العلاجية وما بعد التقييم، مع سرّية كاملة.', 2, true, false, '2026-10-04T11:58:23.440Z'::timestamptz, '2026-10-04T11:58:23.440Z'::timestamptz),
    ('cmutroqtv001quedc34c6sxnr', 'PROTOCOL', 'brotokol-al-khidma-al-ijtimaia', 'بروتوكول الخدمة الاجتماعية', 'منهجية عمل اجتماعي تقوم على التمكين وتحديد الاحتياج والتنسيق المؤسسي والعمل مع الأسرة والوقاية من الانتكاسة الاجتماعية.', '<p>إلى جانب الجوانب النفسية هناك واقع اجتماعي: عمل، وسكن، ومصروف، وتعليم، وأوراق. البروتوكول الاجتماعي يتعامل مع هذا الواقع عمليًا لا نظريًا، لأن ما لا يُحلّ في السجل يبقى في الحياة.</p>
<h2>مسارات العمل</h2>
<p>نبدأ من توصيف دقيق للواقع الاجتماعي، لأن التدخل الذي لا يستند إلى وصف دقيق يبقى تنميطًا لا خطة. وبناءً عليه نرتب أولوياتنا بما يخدم مصلحة المستفيد.</p>
<ul>
<li><strong>التمكين:</strong> رفع القدرة الذاتية على العمل والعيش باستقلال مدام، لا عودة إلى التبعية.</li>
<li><strong>تحديد الاحتياج:</strong> السكن والعمل والدعم المعيشي والتعليم والصحة، كل بند على حدة وبتقدير واقعي.</li>
<li><strong>التنسيق المؤسسي:</strong> ربط المستفيد بالجهات المتخصصة وبرامج التأهيل، وما ينسجم منها مع مصلحته.</li>
<li><strong>العمل مع الأسرة المعالة:</strong> خاصة عند وجود أطفال صغار أو كبار سن يعتمدون على المستفيد، لأن هذه المسؤولية تؤثر في جاهزيته للعمل وفي ضغطه النفسي.</li>
<li><strong>الوقاية من الانتكاسة الاجتماعية:</strong> كثير من الانتكاسات تبدأ من موقف اجتماعي كالرفض أو الخلاف أو الشعور بالإقصاء.</li>
</ul>
<p>وما لا نفعله جزء من البروتوكول لا استثناء فيه: لا نقدّم استشارة قانونية ولا مشورة مالية، ولا نتدخل في نزاعات العقود أو المستحقات. وكل ما يحتاج خبرة قانونية أو مالية نحيله إلى الجهة المختصة، ونرشد المستفيد إلى طريقه بوضوح.</p>', 'HandHeart', NULL, NULL, 'من يحتاج دعمًا اجتماعيًا أو تنسيقًا مع جهة أو مؤسسة، ومن يعتمد عليه آخرون في بيئته.', '[]', '[]', '["خريطة واقعية ومكتوبة للاحتياجات الاجتماعية","تنسيق فعلي مع الجهة المختصة بدل التأخير","وضوح في المسؤوليات تجاه من يعتمدون على المستفيد","أدوات عملية للتعامل مع موقف اجتماعي صعب"]', '["لا نقدّم استشارة قانونية ولا مشورة مالية، ونحيل ما يحتاج ذلك إلى الجهة المختصة.","لا تُناقَش أي حالة فردية مع جهة خارجية دون موافقة المستفيد.","العمل مع الأسرة لا يعني إفصاحًا عنها، وبقاء موافقة المستفيد شرطًا في كل مرة.","الأولوية لما يعالج خطرًا مباشرًا على سلامة المستفيد أو على من يعتمدون عليه."]', 'متابعة مستمرة بحسب الاحتياج', '[{"question":"هل تساعدونني في استخراج ورقة أو تصفية وضع قانوني؟","answer":"لا، فالاستشارات القانونية ليست في نطاق عملنا. لكننا ندلّك على الجهة المختصة، ونكتب ملخصًا لحالتك الاجتماعية يناسب ما تحتاجه منها."},{"question":"هل أتكلم مع زوجي أو والديّ عن وضعي؟","answer":"لا من تلقاء أنفسنا. نعمل مع الأسرة بطلب المستفيد وموافقته، ولا نفصح عنها دون إذنه الصريح، وتبقى جلساته الفردية سرّية."}]', 'بروتوكول الخدمة الاجتماعية في مركز سوار وعي', 'منهجية خدمة اجتماعية تقوم على التمكين وتحديد الاحتياج والتنسيق المؤسسي والعمل مع الأسرة والوقاية من الانتكاسة الاجتماعية.', 3, true, false, '2026-10-04T11:58:23.444Z'::timestamptz, '2026-10-04T11:58:23.444Z'::timestamptz),
    ('cmutroqtz001ruedcmpnrdhx2', 'PROTOCOL', 'brotokol-irshad-al-taafi', 'بروتوكول إرشاد التعافي', 'منهج إرشادي يقوم على السؤال والمرافقة بدل النصيحة الجاهزة، ويعمل على الوعي بالذات وصناعة المعنى والدافعية والاستعداد للانتكاسة.', '<p>الإرشاد في التعافي ليس نصيحة عامة من نوع «قلّل الطلب»، بل علاقة مساعدة يرى فيها المستفيد واقعه بوضوح، ويصنع فيه معنى، ويتخذ قراره بنفسه.</p>
<h2>ما الذي يميّز الإرشاد عن العلاج؟</h2>
<p>الفرق جوهري في موقع القرار. الإرشاد يفتح الأبواب ويطرح الأسئلة، ويبقى القرار ملك المستفيد وحده. ونبقى على هذا المبدأ في كل الأحوال، حتى حين نختلف معه على قرار.</p>
<ul>
<li><strong>الإرشاد يسأل ولا يُقرّر:</strong> من يملك القرار هو من يعيش نتيجته بعد ذلك.</li>
<li><strong>فتح الوعي:</strong> نعمل على فهم آلية السلوك بدل اتهام الضمير، وهذا فرق بسيط في المعنى كبير في الأثر.</li>
<li><strong>صناعة المعنى:</strong> لماذا يستحق التغيير؟ وما الذي يجعله يستحق العناء في نظر المستفيد نفسه؟</li>
<li><strong>تقوية الدافعية:</strong> البحث عن الدوافع الداخلية التي تدفع إلى التكرار، لا الاكتفاء بالخوف من الأضرار.</li>
<li><strong>الاستعداد للانتكاسة:</strong> خطة مكتوبة قبل الحاجة إليها لا بعدها.</li>
</ul>
<p>ولا نستخدم لغة وعود ولا نَعِد بنتيجة ولا بجدول زمني دقيق للتعافي. ونبقي ذلك ثابتًا في كل الأحوال، حتى حين نختلف مع قرار المستفيد، فاختلافنا لا يساوي حقه في الاختيار.</p>', 'Compass', NULL, NULL, 'من يحتاج إلى من يسأله ويصغي إليه ويدلّه دون أن يحكم عليه أو يفرض عليه.', '[]', '[]', '["قرار تعافي صادر عن المستفيد نفسه","خطة مكتوبة للاستعداد للانتكاسة","فهم أوضح لدوافع السلوك بدل لوم الضمير","قدرة على مراجعة الدافعية عند تراجعها"]', '["المُرشد يسأل ويدعم ولا يتخذ قرارًا مكان المستفيد.","لا نَعِد بنتيجة ولا بجدول زمني دقيق للتعافي.","ما يُقال في الإرشاد يبقى طيّة السرّية المهنية.","قد نطلب من المستفيد إحاطة أهله إذا رأينا خطرًا حقيقيًا، ونُعلمه بهذا الحد قبل أن يحدث، لأن العلاقة لا تقوم على من لا يعرف حدودها."]', 'متابعة دورية', '[{"question":"هل يخبرني الإرشاد بما أفعله بالضبط؟","answer":"لا. يعرض بدائل واقعية ويشرح ما يتركه كل بديل وما يحمله، ثم تبقى أنت من يقرر في ضوء ذلك."},{"question":"هل يختلف الإرشاد أحيانًا في قراري؟","answer":"قد يختلف، وهذا يجوز. لكن الاختلاف يُقال بوضوح واحترام، ويبقى القرار لك، ولن نضغط عليك بأي شكل من الأشكال."}]', 'بروتوكول إرشاد التعافي | سوار وعي', 'منهج إرشادي يقوم على السؤال والمرافقة لا على المفاضلة، ويعمل على الوعي بالذات وصناعة المعنى والدافعية والاستعداد للانتكاسة.', 4, true, false, '2026-10-04T11:58:23.448Z'::timestamptz, '2026-10-04T11:58:23.448Z'::timestamptz),
    ('cmutroqu4001suedcfbxbua59', 'PROTOCOL', 'brotokol-al-irshad-al-dini', 'بروتوكول الإرشاد الديني', 'مسار اختياري محترم لمن يجد فيه معنى ومصدر دعم، لا أداة ضغط ولا شرط للمشاركة في باقي البرامج.', '<p>الدين جزء من هوية كثير من المستفيدين، واستبعاده من تعافيه قد يعني استبعاد جزء من دوافعه الحقيقية. لذلك نقدّم الإرشاد الديني كأحد المناهج الإرشادية، لا كأداة ضغط أو محاسبة.</p>
<h2>ماذا يشمله الإرشاد الديني؟</h2>
<p>يُقدَّم الإرشاد الديني لمن يطلبه فقط، ويُدمج مع بقية جوانب الخطة بحسب رغبة المستفيد لا بحسب تقديرنا لما هو الأنسب له. ولأنه أحد الخيارات، فلنا ضوابط لا نتنازل عنها.</p>
<ul>
<li><strong>قراءة دينية للظاهرة:</strong> مقاربة بلغة إيمانية تشرح الظاهرة وآلياتها، فيجد المستفيد تفسيرًا يطمئنه ولا يفقده واقعية.</li>
<li><strong>العبادة كمنظّم للتعافي:</strong> الصلاة والذكر وسائر الممارسات التي تمنح اليوم انتظامًا وهدوءًا نفسيًا.</li>
<li><strong>الارتباط بالمعنى:</strong> ربط التعافي بقيم الفرد ومقاصده، لا بالخوف من الضرر وحده.</li>
<li><strong>المشاعر المرتبطة بالذنب:</strong> الخوف من العقاب، وشعور التقصير، والحكم على النفس، والتركيز على ما أخطأ به لا على ما لم يخطئ به.</li>
<li><strong>الجمع بين الإرشاد الديني والنفسي:</strong> قراءة تحفظ ظاهر الأمر ولا تتجاوز حدود ما يُعرف علميًا.</li>
</ul>
<p>أما الضوابط فهي واضحة: لا توبيخ ولا حرمان ولا استخدام للدين ضغطًا على المستفيد لاتخاذ قرار. ومن يفعل ذلك لا يمارس إرشادًا بل تحكّمًا، وهو خارج منهجنا تمامًا. وحرّية المعتقد لا محل فيها مساومة.</p>', 'Moon', NULL, NULL, 'من يجد في المعنى والعبادة دعمًا حقيقيًا في مسيرته ويرغب في إدماج ذلك في خطة تعافيه، ومن لا يرى فيه معنى ولا رغبة فيه.', '[]', '[]', '["هدوء نفسي وانتظام في العبادة بحسب رغبة المستفيد","قراءة دينية للظاهرة تطمئن ولا تفقد واقعيتها","معالجة المشاعر المرتبطة بالذنب","الاندماج في بقية البرامج مع بقاء المعتقد منقصًا"]', '["الإرشاد الديني اختياري تمامًا، ولا يلزم أحدًا لتلقيه أو لتلقي غيره.","لا توبيخ ولا حرمان ولا ضغط ديني لاتخاذ أي قرار.","من لا يؤمن أو لا يرى في الإرشاد الديني معنى يشارك في كامل البرامج الإرشادية والنفسية.","الحرية الدينية وحرية المعتقد لا نقاش فيهما، ونحترم أي اختيار."]', 'جلسات دورية لمن يطلبه', '[{"question":"أنا لا أؤمن، هل يمكنني الاستفادة من المركز؟","answer":"التعافي لا يتوقف على المعتقد. كل البرامج هنا متاحة لك دون شرط، والإرشاد الديني واحد من الخيارات لا شرط في غيره."},{"question":"هل يرشدني المركز إلى واجب أو أمر؟","answer":"الإرشاد الديني هنا يقرأ عليك المعنى كما تراه أنت، ولا يفرض عليك شيئًا، ولا يتحول إلى محاسبة أو لوم على أي حال."},{"question":"هل يمكنني الحضور مرة ثم الانسحاب؟","answer":"نعم، ويمكنك الانسحاب منه في أي وقت دون تبرير. ولا يؤثر ذلك على بقية برامجك إطلاقًا."}]', 'بروتوكول الإرشاد الديني في التعافي | سوار وعي', 'إرشاد ديني اختياري ومحترم لمن يجد فيه معنى ومصدر دعم، بلا توبيخ ولا حرمان ولا ضغط، وبلا مساس بحرية المعتقد.', 5, true, false, '2026-10-04T11:58:23.452Z'::timestamptz, '2026-10-04T11:58:23.452Z'::timestamptz),
    ('cmutroqri0016uedc42wvulrc', 'SERVICE', 'al-iqtiyani-w-al-alami', 'الرعاية النفسية والعلمية المتخصصة', 'جلسات علاجية لتعديل السلوك عبر المناهج والمدارس العلمية، تتكيّف مع احتياج كل فرد بدل تطبيق نموذج واحد على الجميع.', '<p>هذه الخدمة هي العمود الفقري لبرامجنا. نعمل فيها على فهم العلاقة بين السلوك الذي يزعج الفرد والظروف التي يظهر فيها، ثم نُصمّم معًا خطة عملية قابلة للقياس.</p>
<p>لا نستخدم منهجًا واحدًا للجميع. تبدأ العمل بتقييم شامل يجمع التاريخ الشخصي والأنماط السلوكية والصحة النفسية والظروف المحيطة، ثم نختار الأداة العلاجية الأنسب.</p>
<h2>المدارس العلاجية التي نعمل بها</h2>
<ul>
<li><strong>العلاج السلوكي المعرفي:</strong> مساعدة الفرد على التعرّف على الأفكار التلقائية التي تُقوّي السلوك المزعج، واختبارها، واستبدالها بأفكار أكثر توازنًا.</li>
<li><strong>العلاج المتمركز حول العميل:</strong> مساحة يحكي فيها الفرد قصته بلغته الخاصة، فيجد نفسه مسموعًا قبل أن يبدأ أي تعديل.</li>
<li><strong>العلاج بالفن:</strong> وسيلة تعبيرية غير لفظية تفتح باب المشاعر التي يصعب قولها مباشرة.</li>
<li><strong>العلاج الجماعي:</strong> جلسة جماعية صغيرة يشارك فيها المشاركون التجربة نفسها، فيكتشف كلٌّ منهم أنه ليس وحده.</li>
<li><strong>العلاج المنهجي وغير المنهجي:</strong> الانضباط المنهجي من جهة، والمرونة العملية وخبرة الميدان من جهة أخرى.</li>
</ul>
<h2>كيف تسير الجلسة</h2>
<p>تبدأ الجلسة بمراجعة ما حدث منذ اللقاء السابق، ثم نعمل على المحور الذي اتفقنا عليه. كل جلسة تنتهي بخطوة عملية صغيرة تُنفَّذ قبل اللقاء التالي.</p>
<h2>ما هو خارج نطاق عملنا</h2>
<p>نحن مركز متخصص في الإرشاد ودعم التعافي، وليس مرجعية للتشخيص الطبي أو الوصفات الدوائية. عند الحاجة إلى ذلك نحوّل المستفيد إلى الطبيب المختص، وننسّق مع الأسرة بإشرافها وموافقتها.</p>', 'Brain', '/placeholders/service-therapy.svg', NULL, 'للبالغين والمراهقين الذين يسعون إلى ضبط سلوكياتهم، ولكل من يطلب المساعدة من أجل نفسه أو لأحد أفراد أسرته.', '[{"title":"التقييم الأولي الشامل","description":"لقاء استكشافي يجمع القصة الشخصية، ونمط السلوك، والصحة النفسية، والظروف الأسرية والاجتماعية."},{"title":"صياغة الأهداف","description":"نجلس مع المستفيد لتحديد أولويات التغيير، بأهداف واقعية وقابلة للقياس."},{"title":"تصميم الخطة العلاجية","description":"نختار المنهج الأنسب، ونحدد عدد الجلسات وتوقيتها، ونضع مؤشرات لقياس التقدم."},{"title":"التنفيذ والمتابعة","description":"جلسات منتظمة على دفعات، مع مراجعة دورية للخطة وتعديلها بحسب الاستجابة."},{"title":"الانتقال إلى المتابعة","description":"بعد استقرار الوضع ننتقل إلى متابعة أقل تكرارًا، مع خطة واضحة لمنع الانتكاسة."}]', '["فهم أوضح للسلوك ومحرّكاته بدلًا من الاتهام والذنب","أدوات عملية تُطبَّق فورًا خارج الجلسة","تقليل التعرّض للمواقف التي تسبق الانتكاسة","تحسين القدرة على ضبط المشاعر والانفعال","بناء علاقة علاجية آمنة تقوم على الثقة"]', '["خطة تعافٍ مكتوبة وواضحة","استقرار في جوانب متفق عليها مع المعالج","تقليل المواقف عالية الخطورة","القدرة على التعرّف على علامات الإنذار المبكر"]', '["يُحدَّد المعالج الأنسب بعد التقييم وليس قبله.","تُنفَّذ الجلسات فردية أو جماعية بحسب حاجة كل حالة.","لا نقدّم تشخيصًا طبيًا ولا وصفة دوائية.","كل ما يُقال في الجلسة يبقى طيّة السرّية المهنية."]', 'جلسات فردية · ٥٠ دقيقة', '[{"question":"كم عدد الجلسات المطلوبة؟","answer":"يُحدَّد بعد التقييم الأولي. تبدأ معظم البرامج بجلسات منتظمة على دفعات، ثم تنتقل إلى متابعة أقل تكرارًا. المهم هو الاتساق والحضور."},{"question":"هل العلاج فعّال مع جميع الحالات؟","answer":"تختلف الاستجابة من شخص لآخر، وبعض الحالات تحتاج تدخلات طبية تتجاوز نطاق العمل النفسي. عندها نوجّهك إلى الجهة المناسبة بكل شفافية."},{"question":"هل يجب حضور الأسرة؟","answer":"دعم الأسرة مهم في استمرار التعافي، ونشجع على إشراكها بالقدر الذي يريح المستفيد، مع احترام خصوصيته تمامًا."}]', 'العلاج النفسي والعلمي المتخصص في تعديل السلوك | سوار وعي', 'جلسات علاج نفسي وعلمي متخصصة في تعديل السلوك وفق مناهج علمية معتمدة، مع خطة فردية مبنية على تقييم شامل.', 1, true, true, '2026-10-04T11:58:23.358Z'::timestamptz, '2026-10-04T11:58:23.358Z'::timestamptz),
    ('cmutroqrm0017uedcdzyr3ixs', 'SERVICE', 'al-brhamin-al-ilajiya', 'البرامج العلاجية والإرشادية لإعادة التأهيل', 'برامج مطولة ومختصرة لإعادة تأهيل من يسعى إلى التعافي، مصمّمة على مراحل واضحة من التقييم حتى المتابعة.', '<p>البرنامج يجمع بين الجلسات الفردية والعمل الجماعي والتدخلات المساندة. المستفيد لا يجلس في غرفة الانتظار، بل يشارك في عملية مُنظَّمة لها بداية ونهاية ومخرجات واضحة.</p>
<h2>لماذا البرنامج بدل الجلسات المتفرقة؟</h2>
<p>التعافي عملية تحتاج بنية. البرنامج يضع المستفيد في مسار متدرّج: تقييم، ثم تهيئة، ثم تغيير، ثم تثبيت. كما يوفّر إيقاعًا أسبوعيًا ثابتًا يسهّل بناء العادات.</p>
<h2>مكوّنات البرنامج</h2>
<ul>
<li>تقييم شامل في الأسبوع الأول.</li>
<li>جلسات فردية لتعديل الأنماط السلوكية والصوت الداخلي.</li>
<li>جلسات جماعية أسبوعية لتبادل الخبرات ودعم الالتزام.</li>
<li>جلسات أسرية عند الحاجة وبموافقة المستفيد.</li>
<li>أنشطة مساندة بحسب البرنامج.</li>
<li>جلسات متابعة بعد إنهاء البرنامج الأساسي.</li>
</ul>
<h2>أنواع البرامج</h2>
<p>نوفّر برامج مطولة تعتمد على البنية والمرحلة، وبرامج مختصرة مركّزة على هدف محدد. ويُختار النوع بعد التقييم الأولي.</p>', 'ClipboardCheck', '/placeholders/service-programs.svg', NULL, 'لمن يريد برنامجًا منظّمًا بدل الجلسات المتفرقة، ودرجة الاستعداد لديه قائمة.', '[{"title":"تقييم شامل","description":"تحديد مستوى الخطورة والحاجات والدعم المتاح، وصياغة أهداف واضحة."},{"title":"التهيئة والتثقيف","description":"تعزيز الدافعية، وشرح آلية عمل البرنامج، وبناء الالتزام."},{"title":"المرحلة العلاجية","description":"العمل المنظّم على تعديل السلوك وبناء المهارات اللازمة للتعامل مع الضغوط."},{"title":"التأهيل وإعادة البناء","description":"إعادة بناء العلاقات والمهارات الحياتية، وفتح مسارات للنشاط والهدف."},{"title":"التثبيت والمتابعة","description":"تقليل وتيرة الجلسات مع خطة واضحة لمنع الانتكاسة."}]', '["مسار واضح بمراحل بدل العلاج المتقطع","إيقاع أسبوعي ثابت يدعم بناء العادات","متابعة الفريق لنفس الحالة من البداية للنهاية","أدوات عملية للتعامل مع الضغوط اليومية","دعم مستمر بعد إنهاء البرنامج"]', '["خطة تعافٍ موثّقة ومفهومة","استقرار في نمط السلوك خلال أسابيع","شبكة دعم نشطة بدل العزلة","قدرة على التعرّف على محفّزات الانتكاسة"]', '["مدة البرنامج ليست ثابتة وتُحدَّد بعد التقييم.","المشاركة الطوعية شرط أساسي لنجاح البرنامج.","يمكن تعديل البرنامج أو إيقافه مؤقتًا عند الحاجة.","البرنامج لا يغني عن المتابعة الطبية إن وُجدت حاجة لها."]', 'من ٤ إلى ١٢ أسبوعًا', '[{"question":"هل يمكن الانتقال من برنامج إلى آخر؟","answer":"نعم، ويحدث ذلك بتقييم دوري. من أظهر تقدمًا ملحوظًا ينتقل إلى برنامج أخف وزنًا، ومن احتاج دعمًا أكبر تُقوّى خطته."},{"question":"هل البرنامج مناسب لمن يعمل؟","answer":"نعم، نراعي توقيت العمل ونحاول جدولة الجلسات بما يناسب الالتزام الوظيفي، مع ترتيبات بديلة عند الحاجة."},{"question":"ماذا لو حدثت انتكاسة أثناء البرنامج؟","answer":"الانتكاسة جزء ممكن من أي مسار تعافٍ وليست نهاية الطريق. نعاملها كإشارة على تعديل الخطة، ونراجع ما يحتاج تغييرًا."}]', 'برامج إعادة تأهيل المدمنين | سوار وعي', 'برامج علاجية وإرشادية مطولة ومختصرة لإعادة تأهيل من يسعى إلى التعافي، بتقييم شامل ومتابعة حتى بعد إنهاء البرنامج.', 2, true, true, '2026-10-04T11:58:23.363Z'::timestamptz, '2026-10-04T11:58:23.363Z'::timestamptz),
    ('cmutroqrq0018uedcad721cnz', 'SERVICE', 'al-irshad-al-usari', 'العلاج والإرشاد الأسري والزواجي', 'دعم الأسرة في احتواء المستفيد والمساعدة في تنفيذ خطة العلاج، مع إشراك الزوجة والزوج في رحلة التعافي.', '<p>الأسرة ليست خلفية لمشكلة الإدمان، بل هي أحد أعمدة التعافي. كثير ممن يعودون إلى الانتكاسة يعودون إلى بيئة لم تتغيّر. لذلك نعمل مع الأسرة بوصفها شريكًا أساسيًا في خطة العلاج.</p>
<h2>ما الذي نعمل عليه مع الأسرة؟</h2>
<ul>
<li><strong>فهم آلية الظاهرة:</strong> معرفة كيف يعمل اضطراب الإدمان ولماذا يتكرر النمط نفسه، دون لوم أو وصم.</li>
<li><strong>تعديل التفاعلات اليومية:</strong> لغة الحوار وحدود السلوك وطريقة تقديم التقدير تؤثر مباشرة في مسار المستفيد.</li>
<li><strong>بناء مهارات الاحتواء:</strong> كيف يكون الدور الداعم موجودًا دون أن يتحول إلى رقابة أو ضغط.</li>
<li><strong>الإرشاد الزوجي:</strong> استعادة التواصل وحل الخلافات، لأن الجو الأسري المتوتر من أقوى محفّزات الانتكاسة.</li>
<li><strong>التعامل مع الانتكاسة:</strong> ما ينبغي فعله وما ينبغي الامتناع عنه في اللحظة الحرجة.</li>
</ul>
<h2>السرّية</h2>
<p>لا نشارك الأسرة أي معلومات عن المستفيد دون إذنه الصريح، ويمكن أن تبقى الجلسات الفردية سرّية تمامًا إذا طلب ذلك.</p>
<h2>مواد مساندة للأسرة</h2>
<p>إلى جانب الجلسات، نوفّر الأسرة مواد توعوية وورشًا قصيرة حول العلامات المبكرة وكيفية طلب المساعدة.</p>', 'Users', '/placeholders/service-family.svg', NULL, 'أفراد الأسر، والأزواج، وأولياء الأمور، وأي مقدّم رعاية يعيش مع المستفيد أو يتعامل معه يوميًا.', '[{"title":"لقاء تعريفي مع الأسرة","description":"نسمع ما تعيشه الأسرة، ونوضح دور المركز وما يمكنه."},{"title":"التوعية باضطراب الإدمان","description":"شرح مبسّط للظاهرة وآليات الانتكاسة وأسبابها الشائعة."},{"title":"بناء مهارات الاحتواء","description":"تدريب عملي على الحوار وتحديد الحدود والتعبير عن القلق."},{"title":"الإرشاد الزوجي","description":"جلسات لاستعادة التواصل ومعالجة الخلافات المزمنة."},{"title":"المتابعة طويلة المدى","description":"جلسات دورية بعد استقرار الوضع، خصوصًا في بداية التعافي."}]', '["فهم أوضح للظاهرة وتقليل الوصم داخل الأسرة","أدوات عملية للتعامل مع المواقف الصعبة","تقليل التوتر بين الزوجين أو بين الأسرة والمستفيد","بيئة داعمة حقيقية للتعافي","الاستفادة من تجارب أسر سبقتها"]', '["أجواء أسرية أكثر استقرارًا","استجابة أسرع لعلامات الإنذار المبكر","استمرارية أكبر في خطة العلاج","قدرة الأسرة على طلب الدعم في وقتها"]', '[]', 'جلسات أسرية · ٦٠ دقيقة', '[{"question":"هل أستطيع حضور الجلسات دون المستفيد؟","answer":"نعم. يمكن للأسرة طلب جلسات خاصة بها وحدها، وهذا خيار شائع ومفيد خاصة في بداية الطريق."},{"question":"هل نبلغ الأسرة بكل شيء عن المستفيد؟","answer":"لا. نلتزم الموافقة المستنيرة، ولا نشارك أي معلومات دون إذن المستفيد الصريح.عند وجود خطر حقيقي على حياته نلتزم بما تقتضيه الأخلاق والمسؤولية المهنية."},{"question":"ماذا لو كانت الأسرة ممانعة للتعاون؟","answer":"نبدأ عندها من تغيير ما يمكن تغييره: كلّم من يقبل، وركّز على الجانب الذي يرى فيه الآخر قيمة، وابدأ بخطوات صغيرة."}]', 'الإرشاد الأسري والزوجي في تعافي الإدمان | سوار وعي', 'دعم الأسرة في احتواء المستفيد والمساعدة في تنفيذ خطة العلاج، مع إشراك الزوجية في رحلة التعافي.', 3, true, true, '2026-10-04T11:58:23.367Z'::timestamptz, '2026-10-04T11:58:23.367Z'::timestamptz),
    ('cmutroqrv0019uedclwv8r313', 'SERVICE', 'al-tadakhkhulat-al-ijtimaia', 'التدخلات الاجتماعية المتخصصة', 'إعادة تأهيل المستفيد والبيئات الاجتماعية المحيطة به، والعمل مع المدرسة والجامعة والعمل على خفض عوامل الخطر.', '<p>السلوك لا يحدث في فراغ، بل داخل بيئته: الأسرة، والمدرسة، والجامعة، ومكان العمل، والرفاق. لذلك نتعامل مع البيئة بوصفها جزءًا من العلاج لا مجرد خلفية له.</p>
<h2>ماذا نعني بإعادة تأهيل البيئة؟</h2>
<p>أن نعمل مع الجهة على خفض عوامل الخطر ورفع عوامل الحماية، وتوعية الكوادر، وبناء قنوات واضحة لإحالة من يحتاجون إلى المساعدة، وتقليل الوصم.</p>
<h2>مجالات العمل</h2>
<ul>
<li><strong>المدارس والجامعات:</strong> برامج وقائية وتوعوية، وتدريب المرشدين الطلابيين على التعرّف على علامات الإنذار المبكر والإحالة الصحيحة.</li>
<li><strong>مؤسسات العمل:</strong> برامج وقائية، وبرامج تأهيلية لمن يحتاجون إلى إعادة تأهيل مع الحفاظ على مصدر رزقه.</li>
<li><strong>الأسر:</strong> برامج توعية قصيرة وقابلة للتنفيذ في المنزل.</li>
<li><strong>التوعية المجتمعية:</strong> ورش ولقاءات لإزالة الوصم ورفع الوعي بالظاهرة وسبل الحصول على المساعدة.</li>
</ul>
<h2>منهجية العمل</h2>
<p>نبدأ بدراسة الاحتياج، ثم نتفق مع الجهة على مؤشرات نجاح واضحة، ثم ننفّذ ونقيس ونحسّن. وتبقى البيانات قابلة للتتبع دون أن تمسّ بخصوصية أي فرد.</p>', 'Network', '/placeholders/service-social.svg', NULL, 'المدارس والجامعات ومؤسسات العمل، والأسر، وأي جهة تهتم بصحة وسلوك فئتها.', '[{"title":"دراسة الاحتياج","description":"لقاءات مع مسؤولي الجهة لتحديد الاحتياج الفعلي."},{"title":"تصميم البرنامج","description":"بناء محتوى يناسب الفئة المستهدفة، مع مؤشرات نجاح."},{"title":"التنفيذ","description":"تنفيذ الورش بالشراكة مع الجهة وبمشاركة مدرّبين."},{"title":"القياس والمتابعة","description":"قياس الأثر وفق المتفق عليه، وتقديم تقرير ختامي."}]', '["خفض عوامل الخطر في البيئة المحيطة","قنوات واضحة لإحالة من يحتاجون إلى المساعدة","بناء مناعة توعوية داخل المؤسسة","تقليص الوصم داخل المؤسسات","استدامة التغيير عبر تهيئة الكوادر"]', '["زيادة الوعي بطرق طلب المساعدة","انخفاض الوصم تجاه المتأثرين","قدرة الكوادر على التعرّف على علامات الإنذار المبكر","استمرارية الأثر بعد انتهاء البرنامج"]', '["تُنفَّذ البرامج وفق اتفاق يحدّد المسؤوليات والسرّية.","لا تُناقَش أي حالة فردية مع الجهة إلا بموافقة المستفيد.","يمكن تصميم محتوى مخصّص لمؤسسات بعينها."]', 'برامج مؤسسية · حسب الاتفاق', '[{"question":"هل تناسب المدارس والجامعات معًا؟","answer":"نعم، ويُفضَّل فصل المحتوى حسب الفئة العمرية لأن طريقة الطرح والتحدّيات تختلف بينهما."},{"question":"هل توفّرون تقريرًا بعد البرنامج؟","answer":"نعم، نقدّم تقريرًا ختاميًا يتضمن ما نُفِّذ والمؤشرات التي تحققت، دون كشف أي بيانات فردية."}]', 'التدخلات الاجتماعية والوقاية المجتمعية | سوار وعي', 'إعادة تأهيل المستفيد والبيئات الاجتماعية المحيطة به، والعمل مع المدارس والجامعات ومؤسسات العمل على خفض عوامل الخطر.', 4, true, false, '2026-10-04T11:58:23.371Z'::timestamptz, '2026-10-04T11:58:23.371Z'::timestamptz),
    ('cmutroqrz001auedcrgd6t6y4', 'SERVICE', 'manahij-al-ilaj-al-musaed', 'مناهج العلاج المساعد', 'برامج علاج مساند تُدمج مع العلاج الأساسي: التوعية الروحية، والعلاج بالفن، والعلاج بالرياضة، والسايكودراما.', '<p>لا يعالج كل الناس بالكلمات نفسها. العلاج المساعد يفتح قنوات تعبيرية مختلفة، ويُدرَج ضمن الخطة العلاجية بحسب تقييم المعالج وميول المستفيد نفسه.</p>
<h2>المناهج التي ننفّذها</h2>
<ul>
<li><strong>التوعية الروحية:</strong> جلسات هادئة تساعد على استعادة معنى وهدوء داخلي، تُقدَّم باختيارية تامة وتحترم معتقد المستفيد.</li>
<li><strong>العلاج بالفن:</strong> رسم وتلوين ونحت وأداء تكشف مشاعر يصعب التعبير عنها لفظيًا وتُدرّب على ضبط الانفعال.</li>
<li><strong>العلاج بالرياضة:</strong> نشاط بدني منظّم يبني الانضباط ويحسّن المزاج والصحة الجسدية.</li>
<li><strong>السايكودراما:</strong> تمثيل مواقف من الحياة اليومية في بيئة آمنة، ما يساعد على إعادة فهم الموقف والخروج منه.</li>
</ul>
<h2>لماذا ندمجها؟</h2>
<p>الأنشطة الإبداعية والبدنية تمنح المستفيد مساحة يشغل فيها طاقته بدل أن تتحول فائضًا إلى سلوك مزعج، وهي تخدم العلاج النفسي ولا تنافسه.</p>
<h2>اختيار المنهج</h2>
<p>لا تُطبَّق كل المناهج للجميع. يُختار ما يخدم أهداف الخطة ويُقدَّم بترتيب متكامل لا كأنشطة متفرقة.</p>', 'Sparkles', '/placeholders/service-auxiliary.svg', NULL, 'المستفيدون الذين يستجيبون للتجربة أكثر من الحوار، ومن يحتاج خطة مستقرة تجمع أكثر من منظور.', '[{"title":"تحديد الميول","description":"ملاحظة ما يجذب المستفيد: الرسم، أو الحركة، أو التمثيل، أو الهدوء."},{"title":"اختيار المنهج","description":"المعالج يختار ما يخدم أهداف الخطة بالاتفاق مع المستفيد."},{"title":"التنفيذ المنتظم","description":"نشاط أسبوعي في مكان مهيّئ وآمن بإشراف مختص."},{"title":"الربط بالعلاج","description":"مناقشة ما يطرده النشاط داخل الجلسات العلاجية."}]', '["قنوات تعبير متعددة تناسب أنماطًا مختلفة","تنمية مهارات ضبط الانفعال","تحسين المزاج والصحة الجسدية والنوم","تقليل التوتر والاضطراب","اكتشاف جوانب من الذات يصعب الوصول إليها بالحوار"]', '["ممارسة نشاط بنّاء بشكل أسبوعي","قدرة أفضل على التعبير عن المشاعر","استقرار في المزاج العام","استخدام الوقت الفراغي في اتجاه بنّاء"]', '[]', 'أنشطة أسبوعية · ٦٠ دقيقة', '[{"question":"هل التوعية الروحية شرط؟","answer":"لا. هي أحد الخيارات المتاحة، ونقدّمها لكل من يطلبها. لا نُلزم أحدًا بتوجه ديني، ونحترم خصوصية المعتقد."},{"question":"هل العلاج بالرياضة بديل عن العلاج النفسي؟","answer":"لا. النشاط البدني مكمل ممتاز، لكنه يعمل بشكل أفضل حين يقترن بالخطة العلاجية، ونقدّمه ضمن خطة متكاملة."}]', 'العلاج المساعد: الفن والرياضة والسايكودراما | سوار وعي', 'مناهج علاج مساند تُدمج مع العلاج الأساسي: التوعية الروحية، والعلاج بالفن، وبالرياضة، والسايكودراما.', 5, true, false, '2026-10-04T11:58:23.375Z'::timestamptz, '2026-10-04T11:58:23.375Z'::timestamptz),
    ('cmutroqs4001buedchv9ralx8', 'SERVICE', 'warsh-ala-mal-wa-nadawat', 'ورش العمل والندوات والسيمنارات العلمية', ' فعاليات علمية للتعرّف على الظاهرة وطرق مكافحتها والحدّ من انتشارها، موجّهة للمجتمع وللمتخصصين على السواء.', '<p>ندرة المعلومة الدقيقة من أكثر ما يُبقي الظاهرة قائمة. لذلك نُنظّم فعاليات علمية للتعرّف على اضطراب الإدمان وآليته، وعلى سبل مكافحته والحدّ من انتشاره، بلغة يتبسّطها المتخصص وغير المتخصص على السواء.</p>
<p>تجتمع الفعاليات على ثلاثة محاور: فهم الظاهرة كما يشرحها العلم، وتعلّم مهارات التعامل مع من يطلب المساعدة، وبناء وعي مجتمعي دوره الوقائي قبل أن تتحوّل الظاهرة إلى مسألة فردية معزولة.</p>
<h2>محاور الفعاليات</h2>
<ul>
<li><strong>فهم الظاهرة:</strong> ما هو اضطراب الإدمان، وكيف يبدأ ويتطوّر، ولماذا لا تكفي الإرادة وحدها في كل الحالات.</li>
<li><strong>علامات الإنذار المبكر:</strong> ما الذي يستدعي التدخل المبكر، ومتى يكون الاستماع إلى من يطلب المساعدة أهم من نصيحته.</li>
<li><strong>الوقاية والحدّ من الانتشار:</strong> دور الأسرة والمدرسة والجامعة ومكان العمل في رفع عوامل الحماية وخفض عوامل الخطر.</li>
<li><strong>مسارات المساعدة:</strong> كيف يطلب من يطلب المساعدة، وما الخيارات المتاحة له ولأسرته، وإلى أي جهة يُوجَّه الطلب.</li>
<li><strong>تجارب من الميدان:</strong> قراءة في تجارب برامج إعادة التأهيل، وما الذي نجح منها وما الذي تعثّر.</li>
</ul>
<p><strong>إدارة الفعالية:</strong> لكل فعالية محور محدّد ومدة معروفة، يتبعها نقاش مفتوح وأسئلة عامة. ولا تُعرض أي تجربة فردية إلا بإذن صاحبها.</p>
<p>الفعاليات توعوية في المقام الأول، وليست بديلًا عن التقييم الفردي وخطة العلاج. ومن يحتاج إلى خطة علاجية مخصّصة فليتواصل مع المركز على حدة، بسرّية تامة.</p>', 'UsersRound', NULL, NULL, 'المجتمع عمومًا، وأسر من يطلب المساعدة، وطلبة الجامعات، والعاملون في المهن الصحية والتربوية والإعلامية.', '[{"title":"تحديد المحور والجمهور","description":"نُحدّد المحور الرئيسي والجمهور المستهدف قبل الإعلان، حتى يخرج كل فائد بما يناسبه."},{"title":"الإعداد العلمي للمحتوى","description":"يُعِد المحتوى بالرجوع إلى المراجع العلمية المعتمدة، ويُراجَع قبل العرض."},{"title":"تقديم الفعالية","description":"عرض تقديمي يتبعه نقاش مفتوح وأسئلة عامة، دون كشف بيانات أي شخص."},{"title":"توزيع المواد","description":"مواد توعوية مبسّطة وقائمة قنوات لطلب المساعدة تُوزَّع على الحضور."},{"title":"المتابعة","description":"نُتابع مع الجهة المنظِّمة، ونترك الطريق مفتوحًا لمن رغب في متابعة أعمق على حدة."}]', '["معلومات دقيقة عن الظاهرة مبنية على مراجع علمية","كسر الحاجز بين المتخصص والمجتمع بلغة واحدة","قدرة أكبر على التعرّف على علامات الإنذار المبكر","تقليص الوصم عبر حوار لا يستثني أحدًا","قنوات واضحة لطلب المساعدة تبقى متاحة بعد الفعالية"]', '["فهم أوضح لآلية الظاهرة بدل التصورات الشائعة","ثقة أعلى في مخاطبة من يطلب المساعدة","شبكة من الجهات المتخصصة تسهّل الإحالة","وعي مجتمعي أوسع بخيارات الوقاية والدعم"]', '["الفعاليات توعوية بالدرجة الأولى، ولا تُغني عن التقييم الفردي وخطة العلاج.","لا تُناقَش أي تجربة فردية دون موافقة صريحة من صاحبها.","يُحدَّد عدد المقاعد بحسب القاعة وإتاحة الوقت المخصص للأسئلة.","قد تُنفَّذ بعض الفعاليات عن بُعد بحسب الطلب والظرف."]', 'لقاءات علمية · ٦٠ دقيقة', '[{"question":"هل الفعالية مخصّصة للمتخصصين وحدهم؟","answer":"لا. الجمهور عام، ويُخصَّص جزء من الوقت للجانب المتخصص بحسب طبيعة الفعالية، فلا يغادر أحد دون أن يجد ما ينفعه."},{"question":"هل يمكن الحضور دون تسجيل مسبق؟","answer":"غالبًا نطلب التسجيل المسبق لتنظيم القاعد وتوزيع المواد، وقد تُفتح مقاعد إضافية حسب التوفّر."},{"question":"هل يمكن عقد فعالية لمؤسسة بعينها؟","answer":"نعم، ويُحدَّد المحتوى بحسب الاحتياج الفعلي للجهة، مع مراعاة الفئة العمرية وطريقة الطرح المناسبة لها."}]', 'ورش وندوات وسيمنارات علمية عن الإدمان | سوار وعي', 'فعاليات علمية للتعرّف على الظاهرة وطرق مكافحتها والحدّ من انتشارها، موجّهة للمجتمع وللمتخصصين، بمحتوى مراجَع علميًا.', 6, true, false, '2026-10-04T11:58:23.380Z'::timestamptz, '2026-10-04T11:58:23.380Z'::timestamptz),
    ('cmutroqs8001cuedcct5565vf', 'SERVICE', 'warsh-al-tadrib', 'ورش العمل والحلقات التدريبية والبحثية للعاملين', 'تدريب عملي للعاملين في مجال إعادة تأهيل المدمنين على أحدث المناهج العلمية للتعامل مع الظاهرة في مختلف المجالات.', '<p>من يعمل في هذا المجال يحتاج إلى أكثر من حسن النية. تتغيّر الحالات أمامه، ويُطلب منه قرار في لحظات صعبة، ولا تكفي الخبرة العابرة. لذلك نُخصّص للعاملين ورش العمل والحلقات التدريبية والبحثية، على أن يكون محورها التعريف بأحدث المناهج العلمية كما ترد في الأدبيات ومراجع المجال المعتمدة.</p>
<p>تعمل الحلقات على مبدأ التعلّم بالممارسة: عرضٌ لمنهجية واضحة، ثم تطبيقها على حالات نموذجية، ثم نقاش مفتوح يتبادل فيه المشاركون خبراتهم. والحضور وحده لا يكفي، بل يُتوقع من كل مشارك أن يجهّز حالة يتدرّب عليها قبل الحلقة.</p>
<h2>محاور الحلقات</h2>
<ul>
<li><strong>الأسس العلمية للتقييم:</strong> كيف نقرأ السلوك ونصوغ فرضياته بدل الاكتفاء بما يُقال في الجلسة الأولى.</li>
<li><strong>التعامل مع الانتكاسة:</strong> ما الذي ينبغي فعله في الساعات الأولى، وكيف يوازن العامل بين الحزم والدعم.</li>
<li><strong>مهارات الحوار:</strong> أسئلة مفتوحة تُخرج من الإنكار، وإنصات يخلو من اللوم والاتهام والوعظ.</li>
<li><strong>إدارة الحدود المهنية:</strong> متى وكيف يخرج من الدور العلاجي، ومتى يطلب الاستشارة، وكيف يحمي السرّية.</li>
<li><strong>البحث وتتبّع الجديد:</strong> منهجية قراءة الأدبيات العلمية وتقييمها، ونقل ما ينفع منها إلى الميدان.</li>
</ul>
<p><strong>منهجية العمل:</strong> نبدأ بدراسة احتياج العاملين لا بعرض محتوى جاهز. فالفرق تختلف في طبيعة عملها، وفي المواقف التي تتكرر مواجهتها، وفي مستوى خبرتها، وفي الوقت المتاح لها.</p>
<p>ما يُتعلَّم في الحلقة يحتاج متابعة ميدانية حتى يترسّخ، ولذلك نحرص على تواصل لاحق مع المشاركين بدل أن تنتهي العلاقة بانتهاء القاعة.</p>', 'ScrollText', NULL, NULL, 'العاملون في مراكز إعادة التأهيل، والأخصائيون الاجتماعيون والنفسيون، والمربّون والصحيون المدرسون، وطلبة وعلماء البحث في المجال.', '[{"title":"دراسة الاحتياج","description":"نستعرض مع الجهة أو الأفراد طبيعة عملهم والتحديات التي يواجهونها في الميدان."},{"title":"بناء المنهج","description":"نُعدّ المحتوى بحسب المستوى، من الأساسيات إلى المناهج المتخصصة."},{"title":"التقديم والتطبيق","description":"عرض يتبعه تمارين على حالات واقعية، مع متابعة منقدّم الحلقة."},{"title":"التغذية الراجعة","description":"لقاء تغذية راجعة فردي أو جماعي يرفع مستوى الأداء ويكشف ما يحتاج إلى صقل."},{"title":"المتابعة والتحديث","description":"إحاطات دورية بما يستجد في المناهج العلمية وتغيّر أساليب العمل."}]', '["اطّلاع على أحدث المناهج العلمية وأدبيات المجال","مهارات تطبيقية تُستعمل في الحالات الصعبة","تجارب متبادلة من مؤسسات تعمل في ظروف مختلفة","تقليص الأخطاء الشائعة في التعامل مع الحالات","شبكة مهنية تسهّل الاستشارة وتبادل المراجع"]', '["ثقة أكبر في التعامل مع الحالات","أدوات جاهزة لتقييم الحالة وصياغة خطة العمل","توحيد فهم المفاهيم الأساسية داخل الفريق","قنوات استشارية تبقى مفتوحة بعد الحلقة"]', '["بعض الحلقات تفترض خلفية سابقة في المجال، ويُحدَّد مستوى المتدرّب قبل التسجيل.","يُحرَص على سرّية الحالات المستخدمة في التطبيق، ولا تُعرض بيانات يمكن التعرّف منها على أصحابها.","الفرق بين المستويات يُبنى على محتوى الحلقة لا على شهادة سابقة.","الحضور وحده لا يكفي، وما يُتعلَّم في الحلقة يحتاج متابعة ميدانية حتى يترسّخ."]', 'حلقات تدريبية · ٦٠ دقيقة', '[{"question":"هل تناسب الحلقة من ليس لديه خلفية في المجال؟","answer":"توجد حلقات تمهيدية لمن يبدأ من الصفر، وحلقات متخصصة لمن سبق له العمل. ويُحدَّد المستوى بعد سؤال وجيز."},{"question":"هل يمكن طلب حلقة مخصّصة لمؤسسة؟","answer":"نعم، ويمكن تصميم المحتوى وورش العمل بحسب طبيعة المؤسسة واحتياج فرقها، مع مراعاة ما يتيسّر في وقت العمل."},{"question":"كيف تُحدَّد مدة الحلقة؟","answer":"تختلف بحسب عمق الموضوع وعدد المشاركين، وتُحدَّد قبل التسجيل ليعرف المتدرّب ما يتوقّعه منذ البداية."}]', 'ورش تدريبية وبحثية للعاملين في إعادة التأهيل | سوار وعي', 'ورش عمل وحلقات تدريبية وبحثية للعاملين في إعادة التأهيل، تعريفًا بأحدث المناهج العلمية وتطبيقًا عمليًا على الحالات.', 7, true, false, '2026-10-04T11:58:23.385Z'::timestamptz, '2026-10-04T11:58:23.385Z'::timestamptz),
    ('cmutroqsd001duedcdht8ojp5', 'SERVICE', 'intilaq-programs-fi-al-madaris', 'الانتقال لتنفيذ برامج إعادة التأهيل', 'برامج تأهيل تُنفَّذ في مدارس وجامعات ومؤسسات عمل، بسرّية تامة ودون وصم أمام الأقران.', '<p>كثير من المستفيدين لا يستطيعون الحضور إلى المركز كل يوم بسبب الدراسة أو العمل. في هذه الحالة تنتقل برامج إعادة التأهيل إليهم بدل أن ينتقلوا هم إلينا، فتُنفَّذ لطالبي الخدمة من مدارس وجامعات ومؤسسات عمل، بسرّية تامة ودون أي وصم أمام الأقران.</p>
<p>السرّية هنا ليست تفصيلًا ثانويًا بل شرط أساسي لاستمرارية المستفيد في البرنامج. لذلك نُوثِّق الاتفاق كتابةً قبل التنفيذ، فلا يُعلَن عن البرنامج بشكل صريح، ولا تُناقَش الحالات أمام بقية المستفيدين، ولا يظهر اسم البرنامج في مواد الإعلان.</p>
<h2>ما الذي يتنقّل مع البرنامج؟</h2>
<ul>
<li><strong>التقييم الفردي:</strong> لأن من يبدأ البرنامج خارج المركز يحتاج إلى خط أساس واضحة قبل تغيير أي شيء.</li>
<li><strong>متابعة منظّمة:</strong> التزام بمواعيد محدّدة ومسار واضح في المراحل، حتى لا يضيع البرنامج بين يوميات الدراسة أو العمل.</li>
<li><strong>الأدوات العملية:</strong> مهارات تُمارَس في الموقع نفسه، مثل ضبط الانفعال وإدارة الضغوط وتجنّب المواقف عالية الخطورة.</li>
<li><strong>قنوات الطوارئ:</strong> وسيلة تواصل واضحة مع المركز عند الحاجة العاجلة، لا تُترك لتقدير المستفيد وحده.</li>
<li><strong>التنسيق مع من حوله:</strong> لأن ما يحدث في البيت وفي مقرّه يؤثر في مسار البرنامج كما في الجلسة داخل المركز.</li>
</ul>
<p><strong>ما لا ينتقل مع البرنامج:</strong> لا ينتقل البرنامج كاملًا في كل الأحوال. حين تحتاج الحالة إلى متابعة مكثّفة أو رعاية يومية، يُفضَّل أن يبدأ المستفيد من المركز ثم ينتقل تدريجيًا إلى برنامج في مقرّه. بهذه الطريقة نحصل على فائدة الانتقال من دون أن نضحي بجودة المتابعة.</p>', 'Building2', NULL, NULL, 'المستفيدون من مدارس وجامعات ومؤسسات عمل، وأسرهم، ومسؤولو المؤسسات التي يستقبلونهم.', '[{"title":"الاتفاق مع الجهة","description":"لقاءات مع الجهة لتحديد الفئة والعدد ومستوى السرّية والترتيبات اللوجستية."},{"title":"التقييم الفردي","description":"تقييم مبسّط لكل مستفيد لتحديد ما يحتاجه فعلًا من البرنامج."},{"title":"بناء الخطة","description":"خطة منظّمة تنسجم مع جدول الدراسة أو العمل، بمواعيد واضحة للقاءات."},{"title":"التنفيذ والمتابعة","description":"تنفيذ الجلسات في الموقع، ومتابعة منظّمة، وتواصل مباشر مع المركز عند الحاجة."},{"title":"المراجعة الختامية","description":"مراجعة ما أُنجز، وتوصيات للاستمرار بعد انتهاء البرنامج، بحسب التقييم الفردي."}]', '["استمرارية البرنامج دون انقطاع بسبب الدراسة أو العمل","سرّية كاملة تحفظ المستفيد أمام الأقران","تطبيق ما يُتعلَّم في بيئته اليومية مباشرةً، فيتحوّل من معلومة إلى عادة","تقليص التعرّض للمواقف عالية الخطورة في مقرّه","ربط أوضح بين الأسرة والمركز عبر المؤسسة"]', '["استمرار في البرنامج رغم انشغال الدراسة أو العمل","استقرار في نمط السلوك مع الانتظام في الحضور","قدرة على إدارة الضغوط في محيطه","قناة تواصل مباشرة مع المركز عند الحاجة"]', '["لا يبدأ أي مستفيد في البرنامج قبل تقييم فردي يحدّد احتياجه الفعلي.","السرّية شرط أساسي، وتُخترم في المواد والورش والتقارير.","إن اشتدّت الحاجة إلى متابعة أكثر كثافة، يُفضَّل العودة إلى المركز.","يُشترط حجز مكان مناسب داخل المؤسسة يحفظ خصوصية اللقاء."]', 'برامج في الموقع · من ٤ إلى ١٢ أسبوعًا', '[{"question":"كيف تحفظون سرّية البرنامج داخل المؤسسة؟","answer":"نتفق مع الجهة على التفاصيل قبل التنفيذ، ونكتفي بما يُقال عن البرنامج دون تسميات تكشف الغرض منه."},{"question":"ماذا لو انقطع المستفيد عن الدراسة أو العمل؟","answer":"يتغيّر الجدول ويُعاد تقييم الخطة بحسب المعطيات الجديدة، ويُفضَّل البدء بجدول أسبوعي مرن يسهل تعديله."}]', 'برامج إعادة التأهيل في المدارس والجامعات ومؤسسات العمل | سوار وعي', 'برامج إعادة تأهيل تُنفَّذ في مدارس وجامعات ومؤسسات عمل بسرّية تامة ودون وصم، مع تقييم فردي ومتابعة منظّمة.', 8, true, false, '2026-10-04T11:58:23.389Z'::timestamptz, '2026-10-04T11:58:23.389Z'::timestamptz),
    ('cmutroqsh001euedc3djlwx63', 'SERVICE', 'al-brhamin-al-tadribiya-li-al-kharidin', 'البرامج التدريبية لتأهيل الخريجين', 'تأهيل الخريجين للعمل في إعادة تأهيل المدمنين، بتكوين يجمع بين الأساس العلمي والمهارات الميدانية.', '<p>هذا المجال لا يحتاج إلى عدد فحسب، بل إلى كوادر تعرف ماذا تعمل وكيف تعمل ولماذا. من هنا نُنفّذ البرامج التدريبية لتأهيل الخريجين للعمل في إعادة تأهيل المدمنين، بجمع بين الأساس العلمي والمهارات الميدانية.</p>
<p>البرنامج مبني على فكرة أن من سيدخل هذا المجال لا يحتاج إلى استظهار ما هو مكتوب، بل إلى فهم كيف تُبنى العلاقة العلاجية، وكيف تُدار الجلسة، وكيف تُحمى السرّية، وكيف نقرأ السلوك دون أحكام مسبقة.</p>
<h2>مكوّنات البرنامج</h2>
<ul>
<li><strong>الأساس العلمي:</strong> فهم الظاهرة وآليتها، وقراءة المراجع، والتمييز بين ما هو مُثبت وما هو شائع.</li>
<li><strong>المهارات الميدانية:</strong> صياغة الأهداف، وإدارة الحوار، والتعامل مع السلوك المزعج في لحظته.</li>
<li><strong>أخلاقيات المهنة:</strong> السرّية، والحدود المهنية، والصدق في وصف ما تراه، ومعرفة الوقت المناسب لطلب الاستشارة.</li>
<li><strong>الجانب الإداري:</strong> التوثيق والمتابعة والكتابة المهنية التي تجعل مسار الحالة قابلًا للرصد.</li>
<li><strong>التطبيق الميداني:</strong> فترات عملية يتمرّن فيها المتدرّب من الملاحظة إلى المشاركة الفعلية تحت إشراف مباشر.</li>
</ul>
<p><strong>ما الذي نعد به وما لا نعد:</strong> لن نعد المتدرّب بوظيفة ولا بدخل محدّد، ولن نكتب عنه تقييمًا يُستخدم خارج المركز دون علمه. وما نقدّمه تكوين منظّم وبيئة تعلّم مهنية وأسندٌ حقيقي حين يبدأ العمل في الميدان.</p>', 'Award', NULL, NULL, 'خريجو الجامعات والكليات الصحية والاجتماعية والتربوية، وكل من تتوفّر لديه الرغبة والالتزام للعمل في هذا المجال.', '[{"title":"التأهيل والتسجيل","description":"مراجعة الشروط الأولية وتسجيل الخريج في المسار المناسب لخلفيته واهتماماته."},{"title":"التأصيل العلمي","description":"فهم الظاهرة، وقراءة الأدبيات العلمية، والتمييز بين المعطيات والتعميمات."},{"title":"المهارات الميدانية","description":"تدريب على صياغة الأهداف وإدارة الحوار والتعامل مع السلوك المزعج."},{"title":"التطبيق بإشراف","description":"ممارسة ميدانية ينتقل فيها المتدرّب من الملاحظة إلى المشاركة الفعلية."},{"title":"الانطلاق المهني","description":"استعداد للعمل مع إسناد ومتابعة، بحسب ما يراه المشرف ملائمًا."}]', '["تكوين يجمع بين الأساس العلمي والمهارة الميدانية","أسس واضحة في أخلاقيات المهنة وحماية المستفيد","مهارة في قراءة المراجع وتمييز المعطيات عن التعميمات","دراية عملية بمتطلبات العمل داخل المركز","فرصة للتدرّب على أرض الواقع بإشراف مباشر"]', '["قدرة على إدارة جلسة إرشادية تحت إشراف مباشر","معرفة عملية بمتطلبات المهنة ومسؤولياتها","سلوك مهني يحفظ كرامة المستفيد وسرّيته","استعداد معقول للانطلاق في سوق العمل"]', '["مدة البرنامج ومكوّناته تختلف بحسب المسار والخبرة السابقة.","التطبيق الميداني يتم داخل المركز وبإشراف مباشر، ولا يغني عن التكوين النظري.","لا يُمنح المتدرّب صلاحية مستقلة في العمل الإكلينيكي قبل استيفاء المتطلبات النظامية.","نتواصل مع الخريج بعد البرنامج بحسب ما يطلبه، احترامًا لخصوصيته."]', 'برنامج تدريبي · من ٤ إلى ٩ أشهر', '[{"question":"هل يُشترط تخصص بعينه؟","answer":"لا يشترط تخصص معيّن، لكن الخبرات السابقة في الصحة أو التربية أو العمل الاجتماعي تجعل التقدّم أسرع."},{"question":"هل يحصل المتدرّب على اعتماد مهني؟","answer":"لا. لا نُصدر اعتمادات مهنية. ما يتلقّاه المتدرّب تكوين منظّم يمكن توثيقه، وخبرة ميدانية تحت إشراف مباشر."},{"question":"هل يمكن البدء في العمل بعد البرنامج مباشرةً؟","answer":"غالبًا يبدأ الخريج بمهام محدودة مع إسناد ومرافقة مشرف، ثم تتّسع مسؤولياته تدريجيًا بحسب تقدير المشرف."}]', 'برامج تأهيل الخريجين للعمل في إعادة التأهيل | سوار وعي', 'برامج تدريبية تؤهّل الخريجين للعمل في إعادة تأهيل المدمنين، بجمع بين الأساس العلمي والمهارات الميدانية وأخلاقيات المهنة.', 9, true, false, '2026-10-04T11:58:23.394Z'::timestamptz, '2026-10-04T11:58:23.394Z'::timestamptz)
on conflict ("id") do nothing;

