insert into posts ("id", "title", "slug", "searchText", "excerpt", "content", "coverImage", "coverImageAlt", "categoryId", "authorId", "status", "publishedAt", "scheduledAt", "seoTitle", "seoDescription", "noIndex", "views", "readingMinutes", "allowComments", "featuredOnHome", "createdAt", "updatedAt") values
    ('cmutroqwg002guedckfc41664', 'الانتكاسة عملية يمكن فهمها، وليست نهاية الطريق', 'al-intikasa-laysat-nihayat-altariq', 'الانتكاسة عملية يمكن فهمها، وليست نهاية الطريق العودة إلى السلوك القديم لا تحدث فجأة ولا بلا سبب؛ فهي نتيجة إشارات تسبقها بأسابيع. تعرّف على مراحل الانتكاسة وعلامات الإنذار المبكر وطريقة التعامل معها بوضوح بدل الذنب.', 'العودة إلى السلوك القديم لا تحدث فجأة ولا بلا سبب؛ فهي نتيجة إشارات تسبقها بأسابيع. تعرّف على مراحل الانتكاسة وعلامات الإنذار المبكر وطريقة التعامل معها بوضوح بدل الذنب.', '<p>حين يمرّ شخص بمدّة من الثبات ثم يعود إلى السلوك الذي توقّف عنه، تسارع إليه كلمة واحدة ثقيلة: «فشل». هذه الاستجابة مفهومة، لأنها مشتقة من صورة ذهنية تربّينا عليها: إمّا أن تنجح وإلّا خسرت كل شيء. غير أن الانتكاسة في أغلب الحالات لا تحدث فجأة ولا بلا سابق إنذار؛ إنها نتيجة سلسلة إشارات تراكمت بصمت، وكثير منها كان يمكن رصده قبل أسابيع من وقوعها.</p>
<p>حين نضع الانتكاسة في إطار «عملية» بدل إطار «انهيار»، يتغيّر مسار التعامل معها: يبدأ الحوار من السبب بدل الاتهام، ومن تعديل الخطة بدل تكرار العتاب، ومن خطوات صغيرة مكتوبة بدل وعود لحظية تنتهي بانتهاء الليلة. هذا التحوّل في طريقة الفهم هو أهم نقطة انطلاق عملية في رحلة التعافي، لأنه يحوّل خبرة مؤلمة إلى معلومة قابلة للاستخدام في الجولة القادمة.</p>
<h2>لماذا نتحدث عن مراحل بدل لحظات</h2>
<p>النموذج المرحلي للتغيّر يفسّر أن السلوك يمر بأطوار متعاقبة، وأن ما يبدو للمشاهد عودةً إلى نقطة البداية قد يكون جزءًا من العملية نفسها. والانتكاسة تمرّ هي الأخرى بما يشبه المراحل: إشارات إنذار صامتة، ثم تصاعد في الرغبة، ثم مرحلة من التسويف والتأجيل، ثم الاستعمال نفسه. وفهم هذه السلسلة يمنح الفرد فرصة للتدخل في نقطة أسبق وأخفّ كلفة، بدل انتظار النتيجة النهائية.</p>
<ul>
<li><strong>إشارات داخلية:</strong> أفكار متكررة عن الموقف نفسه، رغبة في العودة إلى الأشخاص أو الأماكن المرتبطين بالسلوك القديم، توتر أو ملل شديد، وخلاصة ذهنية تقول إن المحاولة لن تنجح.</li>
<li><strong>إشارات خارجية:</strong> خلاف متكرر في البيت، ضغط عمل أو التزامات مالية، موقف أغضب الفرد، أو انقطاع مفاجئ عن جلسات المتابعة.</li>
<li><strong>تغيّرات في الروتين:</strong> تخطي مواعيد أو وجبات، سهر متكرر، انسحاب من النشاطات التي كانت جزءًا من التعافي، ثم تآكل الدافعية تجاه ما كان يميّزه.</li>
<li><strong>ما بعد ذروة الرغبة:</strong> بعد مرور أسرع لحظات الشوق، يبقى تعب جسدي وذهن مشوش؛ وهي أضيق نقطة في المسار كله، ومكان مناسب عادةً لطلب المرافقة.</li>
<li><strong>مفردات مقلقة:</strong> عبارات مثل «مرة واحدة لا تُفرق» أو «أنا لا أستطيع التوقف الآن»؛ وهذه جمل تستحق التوقّف عندها والمراجعة قبل الإجابة.</li>
</ul>
<p>لاحظ أن هذه الإشارات قد تسبق السلوك بشهر أو حتى بسنوات في بعض الحالات، وبعضها لا يُظهره الفرد من تلقاء نفسه. ولهذا فإن أفضل ما يفعله المرافق أو المعالج هو أن يطرح سؤالين بسيطين: «ما أكثر أسبوع شعرت فيه بأنك قريب من الانتكاسة؟» و«ما الذي فعلته في ذلك الأسبوع؟». الإجابة عنهما تمنح خريطة أولية تدلّ على المواقف والأشخاص والأوقات الأكثر خطورة.</p>
<blockquote>الانتكاسة ليست دليلًا على أنك لن تستطيع، بل هي معلومة عن ظاهرة لم تُفهم بعد. من يقرأ إشاراتها مبكرًا يختصر المسافة بين لحظة الانتباه ولحظة الانزلاق.</blockquote>
<h2>ماذا تفعل بعد وقوعها</h2>
<p>الأولوية في الساعات الأولى ليست اللوم، بل الأمان والصدق مع النفس. من يخفي الموقف خوفًا من الانتقاد يتأخر في طلب المساعدة، ومن يعالجه باحترام يجد خطة توضع له في اليوم نفسه. وبعد مرور بضع ساعات يمكن ترتيب الخطوات بترتيب عملي بسيط.</p>
<ol>
<li>أبلغ شخصًا واحدًا على الأقل، ويفضّل مختصًا أو شخصًا تثق به؛ فالسرّية تزيد الحمل ولا تنقصه.</li>
<li>تأكّد من عدم وجود خطر على الصحة، خصوصًا إذا كانت هناك مواد أو جرعات معروفة، واستشر مختصًا عند الحاجة.</li>
<li>احتفظ بتفاصيل ما حدث: المكان، والوقت، وما الذي شعرت به، وما الذي سبقه. هذه المادة الخام للجلسة القادمة.</li>
<li>أعد إلى الجدول اليومي بأبسط صورة ممكنة: مواعيد ثابتة، ووجبات ونوم، ونشاط حركي خفيف.</li>
<li>احجز موعد المتابعة في أقرب وقت، واذكر في المكالمة بصراحة أن الانتكاسة قد وقعت، لأن تفاصيلها تغيّر خطة العمل.</li>
</ol>
<p>لا يعني هذا أن الرحلة عادت إلى الصفر. كثير ممن يمرّون بانتكاسة يواصلون تعافيهم بعدها، وقد تصبح الجولة التالية أوضح لأن المواقف مرتفعة الخطورة لم تعد مجهولة. والأهم أن تُقرأ الانتكاسة كبيانات لا كحُكم؛ وفي كل مرة تُقرأ بهذه الطريقة يقلّ تحمّلها النفسية في المرة القادمة.</p>
<h2>لماذا تُبنى خطة الوقاية قبل وقوعها</h2>
<p>الخطة الوقائية الجيدة لا تُكتب في يوم الانتكاسة، بل في أيام الثبات حين يكون الذهن صافيًا. وهي تجمع ثلاثة أنواع من الإجراءات: إجراءات تُقلّل التعرّض للمواقف مرتفعة الخطورة، وإجراءات تبني توازنًا في الحياة، وإجراءات تحدّد مسبقًا بمَن ستتصل وكيف. حين يكون لكل خطر إجراء مكتوب، يتحوّل الانفعال من شيء يُدار بالمشاعر إلى مهمة لها خطوات واضحة.</p>
<p>نؤكد أن ما سبق إطار تثقيفي عام، وأن ما يناسب كل شخص يحدده التقييم الفردي معه ومع مختصيَّه، فالتشخيص والعلاج المسؤولان يختلفان من حالة إلى أخرى. لا يستطيع أحد أن يَعِد بنتيجة مضمونة، لكن الاستعداد الأفضل متاح للجميع: أن تعرف إشارتك، وأن تجد من يسندك، وأن تتعامل مع الرجوع بوصفه جزءًا من الطريق لا نهايةً له.</p>', '/placeholders/blog-1.svg', 'رسم توضيحي لمراحل الانتكاسة وعلامات الإنذار المبكر', 'cmutroqu9001tuedchqxlrfz3', 'cmutroqn50000uedcovhe8wad', 'PUBLISHED', '2026-10-01T11:58:23.535Z'::timestamptz, NULL, 'الانتكاسة عملية يمكن فهمها: مراحل الإنذار والتعامل معها | سوار وعي', 'الانتكاسة نتيجة إشارات سبق أن ظهرت وليست فشلًا نهائيًا. دليل عملي يشرح مراحل الانتكاسة وعلامات الإنذار المبكر وخطة وقاية تُبنى مسبقًا.', false, 4, 3, false, true, '2026-10-04T11:58:23.537Z'::timestamptz, '2026-10-05T10:05:13.383Z'::timestamptz),
    ('cmutroqwm002iuedcfk0iwytv', 'كيف تدعم أسرتك دون أن تتحول إلى رقابة أو لوم', 'al-ihtiwa-al-usari-duna-arqaba', 'كيف تدعم أسرتك دون أن تتحول إلى رقابة أو لوم الدعم الأسري لا يعني الرقابة ولا الاتهام؛ بل مرافقة تحفظ الكرامة. دليل عملي يوضّح حدود دور الأسرة، وطريقة السؤال المفيدة، والمواقف التي تستدعي جلسة إرشاد أسري.', 'الدعم الأسري لا يعني الرقابة ولا الاتهام؛ بل مرافقة تحفظ الكرامة. دليل عملي يوضّح حدود دور الأسرة، وطريقة السؤال المفيدة، والمواقف التي تستدعي جلسة إرشاد أسري.', '<p>أكثر ما يفسد العلاقة بين الأسرة ومن يطلب المساعدة هو الخلط بين الدعم ومراقبة السلوك. وقد تنشأ النية حسنة تمامًا، لكن شكلها المتكرر يجعلها عبئًا على من يتعافى بدل أن تكون سندًا له. والأسرة التي تتعب من دور المدقّق ترى نفسها ضحية، بينما يشعر الطرف الآخر بأنه تحت المراقبة في كل لحظة، فيتجنب الحديث ويختفي قبل أن يُسأل.</p>
<p>والفرق الجوهري بين المرافقة والرقابة يظهر في نوع السؤال: «كيف أعدّك للمرحلة الصعبة القادمة؟» سؤال في المصاحبة، مقابل «أين ذهبت أمس ومن كان معك؟» سؤال في التدقيق. كلاهما يبدو للبالغ ضروريًا، لكن أثرهما مختلف تمامًا على مسار التعافي وعلى الثقة داخل البيت.</p>
<p>وقبل أن تتعب الأسرة من دورها، من المفيد أن تسأل عنها هي: من يسندني؟ فكثير من الالتزامات الأسرية في هذه المرحلة تمرّ بلا شكر أو اعتراف، فيتراكم الإنهاك حتى تتحول العبارة اللطيفة «أنت معنا دائمًا» إلى شكوى صامتة. وحين يتعب الداعم يتغيّر ما يقدّمه دون أن يشعر، فينقلب من سندٍ إلى مصدر توتر جديد. ولهذا يشمل الإرشاد الأسري القريبين من الشخص المعافٍ، لا المعافي وحده.</p>
<h2>الأسرة بيئة أمان قبل أن تكون مصدر ضغط</h2>
<p>الأسرة بيئة أمان قبل أن تكون مصدر ضغط، ولذلك يبدأ العمل الحقيقي من سؤال بسيط: ما الذي يجعل البيت أقل توترًا لهذا الشخص تحديدًا؟ غالبًا تكون الإجابة تفاصيل يومية صغيرة: موعد رجوع ثابت من العمل، ووجبة في وقت معروف، وغرفة هادئة، وإعلان واضح عن الخلافات داخل البيت بدل إخفائها. هذه التفاصيل لا تبدو كبيرة، لكنها تقلّل عدد المحفّزات التي يستهلك منها الفرد طاقته.</p>
<ul>
<li><strong>المقارنة:</strong> هل تقارنه بشخص آخر في البيت؟ فالمقارنة في سياق التعافي تدفع إلى الخفاء لا إلى الشفافية.</li>
<li><strong>النتائج المفروضة:</strong> هل تفرض مواعيد أو معايير إنجاز دون أن تسأل عن المعوّقات؟ أغلب التعثرات سببها ظرف لم يُذكر.</li>
<li><strong>الورقة الضاغطة:</strong> هل تستخدم فردًا آخر في البيت ورقة ضغط عليك؟ هذا الأسلوب يدمّر الثقة ويزيد المشكلة حجمًا.</li>
<li><strong>التدقيق:</strong> هل تفتح الرسائل أو تتابع تحركاته؟ قد يكون هذا مبررًا في حالات محددة مرتفعة الخطورة، لكنه في غيرها يهدم الاستقلالية ويزيد القلق.</li>
<li><strong>حديث المحيط:</strong> هل تتحدّث عنه أمام غيره؟ تكرار سرد تجربتك في محيطك يحوّلها إلى موضوع فضيحة موقوتة.</li>
</ul>
<blockquote>الأسرة لا تحتاج أن تكون مثالية، بل تحتاج أن تكون متاحة ومستقرة. دورها الحقيقي أن توفّر أمانًا يكفي لينمو فيه التغيير، لا أن تدير تفاصيله.</blockquote>
<h2>ماذا تفعل الأسرة عمليًا</h2>
<p>الأعمال التي تصنع فرقًا في الأسابيع الأولى بسيطة وقابلة للملاحظة: تثبيت موعد العودة من العمل، ومرافقة الحضور إلى الجلسات، وتقليل الإزعاج حول وقت النوم، والجلوس للحديث أسبوعيًا دون شرط ولا سؤال عن التفاصيل. ولا تحتاج هذه الأعمال إلى خبرة، لكن أثرها يحتاج إلى انتظام، فالتكرار اليومي هو ما يجعلها فعّالة.</p>
<ul>
<li>اتفقوا على وقت اتصال ثابت أسبوعيًا حتى في الأيام الجيدة، فالتواصل المنتظم يمنع تراكم سوء الفهم.</li>
<li>اسأل عن الاحتياجات لا عن التفاصيل: «ما الذي تحتاجه هذا الأسبوع؟» أيسر من «كيف تسير الأمور؟».</li>
<li>احتفل بالتقدم بالوصف لا بالحكم: «حافظت على موعدك ثلاث مرات هذا الشهر» أفضل من تلخيص الشهر بعبارة واحدة.</li>
<li>لا تَعِد بمقابل مادي مرتبط بالاستمرار؛ فما يعزّز الاستمرار غالبًا هو الاحترام والدعم اليومي، لا المحفّزات المادية.</li>
</ul>
<p>وفي الوقت نفسه، من حق الأسرة طلب الإرشاد لنفسها. الجلسات الإرشادية الأسرية ليست دليلًا على خلل في البيت، بل تدريب على مهارات التواصل، وتحديد حدود واضحة متفق عليها، وفهم الفرق بين أن تكون سندًا وأن تكون بديلًا عن المعالج أو صديقًا مقربًا له.</p>
<blockquote>الدعم الأسري الحقيقي يُقاس بما يمنحه من مساحة، لا بما يمنعه من خيارات.</blockquote>
<h2>حين يشتدّ الاحتكاك</h2>
<p>قد يصل الاحتكاك بين أفراد البيت إلى درجة لا تُحل بالكلام وحده. عندها يصبح طلب جلسة إرشاد أسرية مع مختص — في بداية الأسبوع عادةً — خطوة عملية مفيدة، لأنها تنقل الحوار من المواجهة العلنية إلى مساحة محايدة. وأحيانًا يكون الفصل المؤقت والمعلَن بين أفراد البيت ضروريًا، وهذا لا يعني قطيعة، بل حماية لما بُني حتى ذلك الحين.</p>
<p>نذكّر بأن ما ورد هنا تثقيفي عام، وأن ما يناسب أسرة بعينها قد لا يناسب أخرى؛ فالظروف النفسية والمادية تختلف، والقاعدة المرنة أعلم من القاعدة الصارمة. وأكبر خطأ ممكن أن تقع فيه الأسرة هو استعجال الحكم على تباطؤ فرد ما، فالتحسّن في التعافي يحتاج غالبًا وقتًا أطول مما نتوقعه جميعًا.</p>', '/placeholders/blog-2.svg', 'رسم يوضّح الفرق بين الدعم الأسري ومراقبة السلوك', 'cmutroquf001vuedc56sabb3k', 'cmutroqn50000uedcovhe8wad', 'PUBLISHED', '2026-09-22T11:58:23.541Z'::timestamptz, NULL, 'دعم الأسرة دون رقابة أو لوم: حدود واضحة ومهارات تطبيقية | سوار وعي', 'كيف تحافظ الأسرة على كرامة من يطلب المساعدة؟ تفرّق عملي بين المرافقة والرقابة، مع أسئلة مفيدة وحدود متفق عليها ومواقف تستدعي الإرشاد الأسري.', false, 4, 3, false, false, '2026-10-04T11:58:23.543Z'::timestamptz, '2026-10-05T10:05:13.362Z'::timestamptz),
    ('cmutroqws002kuedcbdmdn6ro', 'النوم والضغط النفسي وضبط الانفعال في التعافي المبكر', 'al-nawm-w-al-daghatt-al-nafsi-w-dabt-al-infeel', 'النوم والضغط النفسي وضبط الانفعال في التعافي المبكر اضطراب النوم وتراكم الضغط يضعفان ضبط الانفعال في أسابيع التعافي الأولى. تعرّف على أسباب الأرق في هذه المرحلة، وخطوات لخفض الضغط، وأدوات بسيطة للتعامل مع موجة الانفعال.', 'اضطراب النوم وتراكم الضغط يضعفان ضبط الانفعال في أسابيع التعافي الأولى. تعرّف على أسباب الأرق في هذه المرحلة، وخطوات لخفض الضغط، وأدوات بسيطة للتعامل مع موجة الانفعال.', '<p>الأسابيع الأولى من التعافي هي الفترة التي يشتكي فيها أغلب المستفيدين من اضطراب النوم واضطراب في ضبط الانفعال معًا. والسبب شائع جدًا: الجهاز العصبي الذي اعتاد سنوات من الاستيقاظ المتكرر يحتاج وقتًا كي يعيد ضبط إيقاعه، ويحتاج هذا الوقت غالبًا أكثر مما يظنه الفرد وأسرته.</p>
<p>النوم ليس رفاهية تؤجل حتى تنتهي المهام، بل عنصر أساسي في خطة التعافي. فالسهر المتكرر يزيد تهيج الانفعال، ويضعف التحكم في الرغبات، ويجعل المواقف اليومية تبدو أكبر من حجمها الحقيقي. وحين يتراكم النقص في النوم ظهر أثره في التنقل بين الجلسات، وفي تحمل المخاطرة، وفي العلاقة بالأسرة.</p>
<h2>من أين يأتي اضطراب النوم في هذه المرحلة</h2>
<ul>
<li><strong>ساعة بيولوجية مضطربة:</strong> سنوات من نمط معكوس بين الليل والنهار لا تختفي في أسبوع، والنوم النهاري القصير المتكرر يقطع مرحلة الراحة العميقة.</li>
<li><strong>قلق ما قبل النوم:</strong> أفكار متكررة عن يوم الغد، عن المال، أو عن وتيرة التعافي نفسها، فيبقى الذهن مشغولًا حتى مع الإغلاق المبكر للعين.</li>
<li><strong>منبهات في الغرفة:</strong> الجوال والضوء والأصوات، وهي أسباب شائعة يسهل معالجتها دون أي جهد.</li>
<li><strong>أعراض جسدية:</strong> صداع الصباح ووجع المفاصل عند الاستيقاظ، وهما علامتان على أن الراحة لم تكتمل.</li>
</ul>
<p>الخبر المطمئن أن هذا الاضطراب يتحسّن غالبًا خلال الأسابيع الأولى بمجرد ضبط الأوقات وتقليل المنبهات. والحل هنا لا يبدأ من قائمة أدوية، بل من ثلاث خطوات تتكرر كل يوم: تثبيت وقت الاستيقاظ، وتثبيت وقت الذهاب إلى الفراش، وحركة بدنية منتظمة. وقد يبدو الأمر بسيطًا، لكن اتساقه هو ما يعيد ضبط الإيقاع، لا مقدار ما يُفعل في اليوم.</p>
<p>وحين يكون الأرق هو الشكوى الأساسية، يفيد روتين قصير قبل النوم يُعاد كل ليلة: إطفاء الأنوار، وخفض إضاءة الشاشة، وكتابة ما يشغل الذهن في ورقة حتى يخرج من رأسه، ثم قراءة هادئة. الغرض ليس إلقاء الفرد في النوم قسرًا، بل أن يتعلّم أن الاسترخاء نتيجة متكررة لسلوك ثابت لا حظ عابر.</p>
<h2>الضغط النفسي حين لا ينخفض</h2>
<p>الضغط في هذه المرحلة له شكل خاص: يبدأ من شعور منخفض بقدرة الفرد على إدارة حياته، ثم تتراكم فوقه مواعيد العلاج وطلبات الأسرة والتوقعات الاجتماعية، فيبدو وكأن الضغط لا ينقص من أي جهة. ويزيد الأمر أن كثيرًا من هذه الطلبات تتزامن في أسابيع قليلة، فيتحول الشهر إلى سلسلة مواعيد متجاورة بلا مساحة بينها.</p>
<p>الخطأ الشائع الأول أن يُعامل الفرد ضغطه على أنه ضعف شخصي، فيكبت نفسه ويزيد الحمل. والخطأ الثاني أن يربط الضغط وحده بالانتكاسة، فيخاف العجز ويتجنّب المواقف الصعبة. أما الأدق منطقيًا فهو أن الضغط إشارة تستدعي تعديلًا، لا حكمًا على الشخص.</p>
<ol>
<li>قسّم ما تشعر به إلى أجزاء مسمّاة، فعادةً يصبح الشعور العام أثقل بمجرد تمييز أجزائه.</li>
<li>افصل بين ما يمكن التأثير فيه وما لا يمكن: ركّز خطتك على الأسبوع الأول فقط، واترك ما بعده خارج حسابك الآن.</li>
<li>تدرّج بدل القفز: مهمة واحدة صغيرة كل يوم أفضل من قائمة مهام ترهقك قبل أن تبدأ.</li>
<li>احمِ وقت النوم كما تحمي موعد الجلسة، فالسهر يضاعف تهيج اليوم التالي ويضعف قراراتك.</li>
</ol>
<blockquote>الانفعال في التعافي المبكر يشبه الماء في مسدس: كلما كان المصدر أضيق، كان الرذاذ أبعد. أما الضبط فلا يعني إلغاء المشاعر، بل توسيع المساحة التي تتحرك فيها.</blockquote>
<h2>ثلاث أدوات يمكن تطبيقها اليوم</h2>
<ul>
<li><strong>سمِّ الشعور:</strong> قل لنفسك «هذا قلق» أو «هذا إحباط» بدل «أنا محبط». التسمية الدقيقة تخفّ شدّة الشعور غالبًا.</li>
<li><strong>تنفّس مطوّل:</strong> شهيق أربع عدّات، وحبس أربع، وزفير ست. ثلاث جولات كافية عادةً لخفض موجة انفعال سريعة.</li>
<li><strong>القاعدة العشر:</strong> إذا لم تستطع حل الموقف الآن، أجّل القرار عشر دقائق واشغل نفسك بمهمة بسيطة، فأغلب القرارات المتسرّعة في أيام الضغط تُندم لاحقًا.</li>
</ul>
<p>وأخيرًا، إذا استمر اضطراب النوم أو صعوبة ضبط الانفعال أكثر من بضعة أسابيع رغم ضبطك للروتين، فهذا سبب كافٍ لطلب تقييم متخصص. فالتقييم المبكر يساعد على تمييز ما هو ضغط مرحلي عابر وما يحتاج إلى تدخل متخصص، وقد يشمل الدعم الدوائي الذي يحدده الطبيب المختص بعد الفحص.</p>
<p>وهذا ما نؤكد عليه دائمًا: المحتوى هنا تثقيفي ولا يُغني عن الاستشارة المباشرة. نتائج التعافي تختلف من شخص إلى آخر بحسب تقييمه الفردي، ولا توجد وصفة مضمونة، لكن الاستعداد الجيد — نوم منتظم، وضبط للانفعال، وخطة مكتوبة — يصنع غالبًا فرقًا محسوسًا في جودة الأيام وطول مدتها.</p>', '/placeholders/blog-3.svg', 'رسم يوضّح أثر قلة النوم والضغط على ضبط الانفعال', 'cmutroquc001uuedc8msjuy2y', 'cmutroqn50000uedcovhe8wad', 'PUBLISHED', '2026-09-08T11:58:23.547Z'::timestamptz, NULL, 'النوم والضغط وضبط الانفعال في التعافي المبكر | سوار وعي', 'دليل تثقيفي يشرح أسباب اضطراب النوم في أسابيع التعافي الأولى، وخطوات عملية لخفض الضغط، وأدوات بسيطة لضبط موجة الانفعال.', false, 4, 3, false, false, '2026-10-04T11:58:23.548Z'::timestamptz, '2026-10-05T10:05:13.384Z'::timestamptz)
on conflict ("id") do nothing;

