insert into pages ("id", "slug", "title", "subtitle", "content", "seoTitle", "seoDescription", "noIndex", "isPublished", "updatedAt", "createdAt") values
    ('cmutroqwx002luedcn7m2ou7q', 'privacy', 'سياسة الخصوصية', 'كيف نتعامل مع بياناتك ولماذا', '<p>آخر تحديث: <span data-current-year>٢٠٢٦</span>. هذه السياسة توضّح كيف يتعامل مركز سوار وعي مع البيانات الشخصية التي يقدّمها زوّار الموقع والمستخدمون لخدماتنا.</p>
<h2>١. من نحن ومبدأنا الأساسي</h2>
<p>مركز سوار وعي هو مركز متخصص في علوم التعافي. نلتزم في كل ما نجمعه من بيانات بمبدأ <strong>البيانات الضرورية فقط</strong>: لا نطلب إلا ما نحتاجه لتقديم الخدمة المطلوبة، ولا نستخدم البيانات لأي غرض آخر.</p>
<h2>٢. البيانات التي نجمعها</h2>
<ul>
<li><strong>بيانات التعريف والتواصل:</strong> الاسم، رقم الجوال، والبريد الإلكتروني.</li>
    <li><strong>بيانات الطلب:</strong> الخدمة التي تسأل عنها، والوقت المفضّل للقاء، وصفة مقدّم الطلب.</li>
<li><strong>السجلات العلاجية:</strong> تُحفظ في نظام منفصل ومشفّر، ولا تُعرض إلا للمختصين المعنيين بالحالة.</li>
<li><strong>بيانات تقنية:</strong> نوع المتصفح والصفحة التي زرتها وبيانات الشبكة، لتحسين أداء الموقع وحمايته.</li>
</ul>
<h2>٣. كيف نحمي بياناتك</h2>
<ul>
<li>تخزَّن أرقام الجوال والبريد والنصوص الحسّاسة <strong>مشفّرة</strong> في قاعدة البيانات، ولا تُخزَّن كنص مقروء.</li>
<li>الوصول إلى لوحة التحكم مقيّد بالصلاحيات، وكل عملية تعديل تُسجَّل في <strong>سجل النشاط</strong> باسم من قام بها ووقتها.</li>
<li>الموقع يعمل عبر <strong>HTTPS</strong> فقط، والبيانات المنقولة مشفّرة أثناء النقل.</li>
<li>تُحذف البيانات أو تُجهَّل عند انتهاء الغرض من جمعها وفق سياسة الاحتفاظ المعتمدة.</li>
</ul>
<h2>٤. من يطّلع على بياناتك</h2>
<p>يطّلع عليها فريق المركز المختص في تقديم الخدمة فقط، وبالقدر اللازم لأداء واجبه. ولا نبيع البيانات ولا نشاركها مع أطراف تسويقية أو إعلانية.</p>
<h2>٥. حقوقك</h2>
<p>يحق لك في أي وقت:</p>
<ul>
<li>العلم بما لدينا من بيانات عنك والحصول على نسخة منها.</li>
<li>طلب تصحيح بيانات غير دقيقة.</li>
<li>طلب حذف بياناتك، مع مراعاة ما يقتضيه حفظ بعض السجلات لالتزامات مهنية وقانونية.</li>
<li>سحب موافقتك في أي وقت، دون أن يؤثر ذلك على خدمتك قبل السحب.</li>
</ul>
<p>لممارسة أي من هذه الحقوق، راسلنا عبر صفحة «تواصل معنا» أو على بريد المركز المعلن.</p>
<h2>٦. الموافقة</h2>
<p>باستخدامك نماذج الموقع أنت توافق على معالجة بياناتك للأغراض الموضحة أعلاه، وذلك بعد إقرار صريح بموافقتك على سياسة الخصوصية.</p>
<h2>٧. تحديثات السياسة</h2>
<p>قد نحدّث هذه السياسة عند تغيّر خدماتنا أو الأنظمة. سيظهر تاريخ آخر تحديث أعلى الصفحة، ونشجّعك على مراجعتها دوريًا.</p>', 'سياسة الخصوصية | سوار وعي', 'التزام مركز سوار وعي بحماية البيانات الشخصية وفق نظام حماية البيانات الشخصية السعودي.', false, true, '2026-10-04T11:58:23.553Z'::timestamptz, '2026-10-04T11:58:23.553Z'::timestamptz),
    ('cmutroqx1002muedcfffyfk21', 'terms', 'الشروط والأحكام', 'استخدامك للموقع يعني موافقتك على هذه الشروط', '<p>استخدامك لهذا الموقع يعني موافقتك على الشروط التالية. نرجو قراءتها بعناية.</p>
<h2>١. طبيعة الموقع</h2>
<p>هذا الموقع تعريفي بالخدمات التي يقدّمها مركز سوار وعي. <strong>المعلومات المنشورة عليه توعوية عامة</strong> ولا تُعد استشارة طبية أو تشخيصًا أو وصفة علاج.</p>
<h2>٢. الخدمات وطبيعة العلاقة</h2>
<p>الخدمة الفعلية تبدأ بعد <strong>التقييم الفردي</strong> والاتفاق المسبق على الخطة والملاءمة. وما يُذكر على الموقع هو وصف عام للخدمات المتاحة.</p>
    <p>نحن مركز متخصص في الإرشاد ودعم التعافي، ولا نقدّم تشخيصًا طبيًا ولا وصفات دوائية؛ ما من شأنه ذلك يُحوَّل إلى الطبيب المختص.</p>
<h2>٣. الدقة في المعلومات</h2>
    <p>نبذل عناية معقولة في دقة المحتوى، لكن المعلومات قد تُحدَّث أو تتغيّر. وعند وجود حساسية طبية نوصي باستشارة مختص قبل الاعتماد على أي معلومة.</p>
<h2>٤. المواعيد والحجز</h2>
<p>الحجز عبر الموقع <strong>طلب مبدئي</strong> وليس تأكيدًا نهائيًا. نتواصل معك لتأكيد الموعد، وقد يتغيّر الوقت المقترح بحسب جدول المركز.</p>
<h2>٥. السرّية والخصوصية</h2>
    <p>تُعامَل جميع البيانات وفق <a href="/privacy">سياسة الخصوصية</a>. ونلتزم بعدم مشاركة معلومات أي مستفيد مع أي طرف خارجي دون إذنه الصريح.</p>
<h2>٦. استخدام الموقع</h2>
<ul>
<li>لا يُستخدم الموقع لأي غرض غير مشروع.</li>
<li>لا تُحاول الوصول إلى لوحة التحكم أو قواعد البيانات دون تصريح.</li>
<li>لا يُعاد نشر المحتوى دون إذن كتابي من المركز.</li>
</ul>
<h2>٧. إخلاء المسؤولية</h2>
    <p>لا نتحمّل مسؤولية أي ضرر ينتج عن اعتماد معلومة منشورة على الموقع دون استشارة مختص، ولا نتحمّل مسؤولية قرارات تُبنى على هذه المعلومات دون مراجعة مختص.</p>
